"use client";

export { AomiWalletKitContextProvider, useAomiWalletKit } from "./context";
export {
  AomiWalletKitProvider,
  type AomiWalletKitProviderInput,
  type AomiWalletKitProviderProps,
} from "./config";
export type {
  AomiAccount,
  AomiAccountCredential,
  AomiLoginMethod,
  AomiNetworkTarget,
  AomiSessionIdentity,
  AomiSessionStatus,
  AomiTransactionExecution,
  AomiTxResult,
  AomiWalletKit,
  AomiWalletOption,
  PublicWalletFamily,
  SvmCluster,
  SvmNetworkOption,
  SvmWalletDescriptor,
  WalletFamily,
} from "./types";
export {
  AOMI_SESSION_BOOTING_IDENTITY,
  AOMI_SESSION_DISCONNECTED_IDENTITY,
  formatAuthMethod,
  formatWalletAddress,
  formatWalletProvider,
  inferAuthMethod,
} from "./identity";
export {
  AomiWalletNetworkPreferencesProvider,
  useAomiWalletNetworkPreferences,
  useOptionalAomiWalletNetworkPreferences,
} from "./network-preferences";
export {
  canonicalWalletKey,
  normalizeWalletOptionId,
  registerWalletBrand,
} from "./catalog/wallet-branding";
export {
  resolveAomiSvmWalletIds,
  resolveAomiSvmConfig,
  SVM_PRESETS,
} from "./catalog/svm-wallet-catalog";
export type {
  EvmWalletId,
  EvmWalletPreset,
  SvmWalletId,
  SvmWalletPreset,
  WalletId,
} from "./catalog/wallet-ids";
export {
  FullTestnetWalletRouter,
  isFullTestnet,
  useFullTestnet,
} from "./full-testnet-wallet-routing";
export { useWalletActivationGuard } from "./use-wallet-activation-guard";
export { useActionCapabilities } from "./use-action-capabilities";
export { signOutAndDisconnect } from "./account/sign-out";

"use client";

import { createContext, useContext, useEffect, type ReactNode } from "react";
import { useUser } from "@aomi-labs/react";
import { AOMI_SESSION_DISCONNECTED_IDENTITY } from "./identity";
import type { AomiWalletKit } from "./types";

const DISCONNECTED_WALLET_KIT: AomiWalletKit = {
  identity: AOMI_SESSION_DISCONNECTED_IDENTITY,
  isReady: true,
  isSwitchingChain: false,
  canConnect: false,
  canOpenAccountUI: false,
  canDisconnect: false,
  accounts: [],
  selectAccount: async () => undefined,
  evmWallets: [],
  solanaWallets: [],
  socialLoginOptions: [],
  supportedNetworks: {
    evm: [],
    solana: [],
  },
  connect: async () => undefined,
};

const AomiWalletKitContext =
  createContext<AomiWalletKit>(DISCONNECTED_WALLET_KIT);

function toSvmCapabilities(
  capabilities: AomiWalletKit["identity"]["svmCapabilities"],
): string[] | undefined {
  if (!capabilities) return undefined;
  return Object.entries(capabilities)
    .filter(([, enabled]) => enabled)
    .map(([name]) =>
      name.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`),
    );
}

function AomiWalletKitSync({ walletKit }: { walletKit: AomiWalletKit }) {
  const { setUser } = useUser();
  const identity = walletKit.identity;

  useEffect(() => {
    // Account-abstraction and sponsorship are backend authority: they are
    // resolved by the execution-profile endpoint and per-execution operation
    // payloads, never forwarded from identity into user_state. Only FE-owned
    // connection facts (owner, chain, provider, auth) are synced here.
    setUser({
      connection: {
        is_connected: identity.isConnected,
        provider: identity.isConnected
          ? (identity.sessionProvider ?? identity.embeddedProvider ?? null)
          : null,
        auth_method: identity.isConnected ? (identity.authMethod ?? null) : null,
      },
      evm: {
        address: identity.address ?? null,
        chain_id: identity.chainId ?? null,
      },
      svm: {
        address: identity.svmAddress ?? null,
        cluster: identity.svmCluster ?? undefined,
        wallet_name: identity.svmWalletName ?? null,
        transport: identity.svmTransport ?? null,
        capabilities: toSvmCapabilities(identity.svmCapabilities) ?? [],
      },
    });
  }, [
    identity.address,
    identity.authMethod,
    identity.chainId,
    identity.isConnected,
    identity.svmCapabilities,
    identity.svmCluster,
    identity.svmTransport,
    identity.svmWalletName,
    identity.svmAddress,
    identity.embeddedProvider,
    identity.sessionProvider,
    setUser,
  ]);

  return null;
}

export function AomiWalletKitContextProvider({
  children,
  value,
}: {
  children: ReactNode;
  value: AomiWalletKit;
}) {
  return (
    <AomiWalletKitContext.Provider value={value}>
      <AomiWalletKitSync walletKit={value} />
      {children}
    </AomiWalletKitContext.Provider>
  );
}

export function useAomiWalletKit(): AomiWalletKit {
  return useContext(AomiWalletKitContext);
}

"use client";

import type { Chain } from "viem";
import type {
  WalletEip712Payload,
  WalletSolanaSignMessagePayload,
  WalletSolanaSignPayload,
  WalletTxPayload,
} from "@aomi-labs/react";
import type {
  AccountRuntimeStatus,
  AccountWallet,
  AomiUserRef,
  LinkWalletInput,
  LinkedAuthAccount,
  UpdateAccountInput,
  UpdateLinkedAccountInput,
  UpdateWalletInput,
} from "./account/types";
import type { WalletModalRow } from "./composer/merge-wallet-rows";

export type AomiSessionStatus = "booting" | "disconnected" | "connected";
export type WalletFamily = "evm" | "svm";
export type PublicWalletFamily = WalletFamily;
export type SvmCluster = "solana:mainnet" | "solana:devnet" | "solana:testnet";

export type SvmNetworkOption = {
  id: string;
  label: string;
  cluster: SvmCluster;
  rpcHttpUrl: string;
  rpcWsUrl?: string;
  isDefault?: boolean;
};

export type SvmNetworkConfigInput = {
  networks?: readonly SvmNetworkOption[];
  cluster?: SvmCluster;
  rpcHttpUrl?: string;
  rpcWsUrl?: string;
};

export type SvmWalletCapabilities = {
  canSignMessage?: boolean;
  canSignTransaction?: boolean;
  canSignAllTransactions?: boolean;
  canSendTransaction?: boolean;
  canSignAndSendTransaction?: boolean;
};

export type AomiNetworkTarget =
  | { family: "evm"; chainId: number }
  | { family: "svm"; networkId: string };
export type AomiWalletKind = "eoa" | "smart-account";
export type SessionProvider = "para" | "privy" | "custom" | (string & {});
export type EmbeddedProvider = "para" | "privy" | "aomi" | (string & {});
export type AuthProviderId = SessionProvider | "none" | "baseAccount";
export type WalletSource =
  | "injected"
  | "walletconnect"
  | "coinbase"
  | "baseAccount"
  | "embedded"
  | "stored";

export type AomiLoginMethod =
  | "google"
  | "apple"
  | "facebook"
  | "x"
  | "discord"
  | "github"
  | "farcaster"
  | "telegram"
  | "email"
  | "phone"
  | "wagmi"
  | "passkey"
  | "wallet";

export type AomiSessionIdentity = {
  status: AomiSessionStatus;
  isConnected: boolean;
  /**
   * Connected EVM account address (0x...). When `walletKind === "smart-account"`
   * this is the smart account address; when `walletKind === "eoa"` it is the EOA.
   */
  address?: string;
  /** Whether the connected account is an EOA or an always-AA smart account. */
  walletKind?: AomiWalletKind;
  chainId?: number;
  /**
   * Connected SVM (Solana) wallet pubkey, base58. Independent of
   * `address` — a Para-backed session can carry both an EVM and a
   * Solana wallet under one identity.
   */
  svmAddress?: string;
  /** Provider that authenticated the current session. */
  sessionProvider?: SessionProvider;
  /** Provider backing the active embedded wallet, when one is in use. */
  embeddedProvider?: EmbeddedProvider;
  /** How the active wallet signs or connects. */
  walletSource?: WalletSource;
  /** Stable subject inside the wallet provider, when exposed. */
  walletProviderSubject?: string;
  /** Auth method used within the wallet platform (Para OAuth, etc). */
  authMethod?: AomiLoginMethod;
  /** Verified auth value from the wallet platform, such as email or phone. */
  authValue?: string;
  /** Provider verification timestamp for `authValue`, unix seconds. */
  authVerifiedAt?: number;
  primaryLabel?: string;
  secondaryLabel?: string;
  svmCluster?: SvmCluster;
  svmWalletName?: string;
  svmTransport?: "extension" | "embedded" | "mwa";
  svmCapabilities?: SvmWalletCapabilities;
};

/**
 * One installable Solana wallet surface (e.g. Phantom, Solflare). Surfaced
 * by adapters so the UI can render an inline picker instead of guessing
 * the user's preferred wallet. `installed` is true when the wallet is
 * actually detected in the browser; `ready` is true when it can be
 * activated (either Installed or auto-loadable like in-browser providers).
 */
export type SvmWalletDescriptor = {
  name: string;
  ready: boolean;
  installed: boolean;
  iconUrl?: string;
};

export type AomiWalletOptionStatus =
  | "installed"
  | "available"
  | "qr"
  | "unavailable";
export type AomiWalletOptionFamily = WalletFamily | "multichain";
export type AomiWalletOptionKind =
  | "evm"
  | "solana"
  | "walletconnect"
  | "social";

/**
 * One connectable wallet or sign-in surface the adapter can activate.
 * UIs render these as normal wallet rows while the adapter remains free
 * to route the click through Para, Privy, wagmi, wallet-adapter, etc.
 */
export type AomiWalletOption = {
  id: string;
  connectorId?: string;
  label: string;
  family: AomiWalletOptionFamily;
  kind: AomiWalletOptionKind;
  status: AomiWalletOptionStatus;
  installed?: boolean;
  ready?: boolean;
  iconUrl?: string;
  description?: string;
};

export type AomiAccountAction =
  | { kind: "manage"; label?: string }
  | { kind: "disconnect"; label?: string }
  | { kind: "signout"; label?: string };

/**
 * One wallet account known to the adapter, tagged by family. The registry
 * may hold several per family (e.g. MetaMask + Para-embedded EVM), but only
 * one per family is `active` (the live account reported to the backend).
 */
export type AomiAccount = {
  /**
   * Stable id: wagmi connector uid (EVM) or solana wallet name (Solana). When
   * one address is exposed by several connectors (e.g. Rabby impersonating
   * MetaMask via EIP-6963), this is the active/preferred connector's uid.
   */
  id: string;
  family: WalletFamily;
  address: string;
  /** Short display label, e.g. formatted address. */
  label?: string;
  /** Human wallet name, e.g. "MetaMask", "Phantom", "Para". */
  walletName?: string;
  /** Provider that owns this account when it is an embedded/provider wallet. */
  provider?: SessionProvider | EmbeddedProvider;
  /** Runtime wallet kind for UI/account-linking classification. */
  walletKind?: "external" | "embedded" | "smart_account";
  /** EVM chain id of this connection, for per-row network labels. */
  chainId?: number;
  /** All wagmi connector uids exposing this address (EVM, dedup metadata). */
  connectorIds?: string[];
  /** True when this is the live account for its family. */
  active: boolean;
  /**
   * True when this account exposes an in-app management surface (e.g. the Para
   * account modal). UIs render a "manage" affordance for it; external wallets
   * managed only in their own extension (MetaMask, Phantom) leave it unset.
   * The handler is the adapter's `openAccountUI({ family })`.
   */
  manageable?: boolean;
  /** Provider/runtime-owned actions the picker can render without provider
   * branching. When omitted, the composer derives the default manage /
   * disconnect / select action from account state. */
  actions?: readonly AomiAccountAction[];
  linked?: boolean;
  linkedVia?:
    | "para"
    | "privy"
    | "challenge"
    | "import"
    | "observed"
    | (string & {});
  capability?: "read" | "write";
};

export type AomiTxResult = {
  txHash: string;
  txHashes?: string[];
  amount?: string;
  aaRequestedMode?: "4337" | "7702" | "none";
  aaResolvedMode?: "4337" | "7702" | "none";
  aaFallbackReason?: string;
  executionKind?: string;
  batched?: boolean;
  callCount?: number;
  sponsored?: boolean;
  SmartAccount4337?: string;
  Delegation7702?: string;
};

export type AomiTransactionExecution = {
  /** Chain the caller already selected before invoking the transaction path. */
  chainIdAlreadySelected?: number;
};

/**
 * Upstream wallet-provider credential the portal exchanges for an Aomi bearer.
 * Aliased to the client type (the same inline `@aomi-labs/client` edge already
 * used for `GetAccountBearer` below) so the shape cannot drift.
 */
export type AomiAccountCredential =
  import("@aomi-labs/client").ProviderCredential;

export type AomiWalletKit = {
  identity: AomiSessionIdentity;
  isReady: boolean;
  isSwitchingChain: boolean;

  canConnect: boolean;
  canOpenAccountUI: boolean;
  canDisconnect: boolean;

  supportedChains?: readonly Chain[];
  supportedNetworks?: {
    evm: readonly Chain[];
    solana: readonly SvmNetworkOption[];
  };
  selectedSolanaNetwork?: SvmNetworkOption;
  solanaNetworkSwitchRequiresReconnect?: boolean;

  /** All wallet accounts known to the adapter, tagged by family. */
  accounts: readonly AomiAccount[];
  /** Unified picker rows: live accounts, stored account-runtime rows, and options. */
  walletModalRows?: readonly WalletModalRow[];
  accountStatus?: AccountRuntimeStatus;
  accountError?: string;
  accountUser?: AomiUserRef;
  accountLinkedAccounts?: readonly LinkedAuthAccount[];
  accountWallets?: readonly AccountWallet[];
  signOutAccount?: () => Promise<void>;
  deleteAccount?: () => Promise<void>;
  updateAccount?: (input: UpdateAccountInput) => Promise<void>;
  linkWallet?: (input: LinkWalletInput) => Promise<void>;
  updateLinkedAccount?: (input: UpdateLinkedAccountInput) => Promise<void>;
  updateLinkedWallet?: (input: UpdateWalletInput) => Promise<void>;
  unlinkLinkedWallet?: (walletId: string) => Promise<void>;
  unlinkLinkedAccount?: (identityId: string) => Promise<void>;
  /** Make `accounts[id]` the active account for its family. */
  selectAccount: (id: string) => Promise<void>;

  /**
   * Installed/loadable Solana wallets the adapter can attach to. Empty
   * (or undefined) when the adapter doesn't support Solana or has no
   * detected wallets. UIs use this to render an inline picker so users
   * pick their wallet explicitly rather than relying on auto-detection.
   */
  solanaWallets?: readonly SvmWalletDescriptor[];
  /**
   * EVM wallet connectors the adapter can attach to. This keeps the picker
   * wallet-brand-first even when the actual connector plumbing comes from
   * Para/Privy/wagmi.
   */
  evmWallets?: readonly AomiWalletOption[];
  /**
   * Attach a specific EVM wallet by option id (matches `evmWallets[].id`).
   */
  connectEvmWallet?: (id: string) => Promise<void>;
  /**
   * Non-wallet account sign-in options, e.g. Google or email. These are
   * rendered separately from wallet brands so users don't have to learn
   * the underlying provider name.
   */
  socialLoginOptions?: readonly AomiWalletOption[];
  connectSocial?: (id: string) => Promise<void>;
  /**
   * Attach a specific Solana wallet by name (matches
   * `solanaWallets[].name`). The promise resolves once the wallet adapter
   * reports connected (or rejects if the wallet popup is cancelled).
   */
  connectSolanaWallet?: (name: string) => Promise<void>;

  connect: (options?: { family?: PublicWalletFamily }) => Promise<void>;
  openAccountUI?: (options?: { family?: PublicWalletFamily }) => Promise<void>;
  /**
   * Disconnect from the wallet. By default disconnects everything;
   * pass `{ family }` to disconnect a specific family while leaving the
   * other connected (e.g. drop just Solana while keeping the EVM Para
   * session, or vice versa). `{ family: "all" }` clears both.
   *
   * Adapters that can't selectively disconnect should still implement
   * this and disconnect everything regardless of `family`; the picker's
   * per-family sections only rely on a best-effort behavior here.
   */
  disconnect?: (options?: {
    family?: PublicWalletFamily | "all";
    /** Disconnect a single account by `AomiAccount.id` (EVM only). */
    accountId?: string;
    /** Log out the provider that owns the account while preserving unrelated wallets. */
    providerSignOut?: boolean;
  }) => Promise<void>;

  switchChain?: (chainId: number) => Promise<void>;
  selectNetwork?: (target: AomiNetworkTarget) => Promise<void>;

  sendTransaction?: (
    payload: WalletTxPayload,
    execution?: AomiTransactionExecution,
  ) => Promise<AomiTxResult>;
  signTypedData?: (
    payload: WalletEip712Payload,
  ) => Promise<{ signature: string }>;
  signMessage?: (
    payload: WalletEip712Payload,
  ) => Promise<{ signature: string }>;
  /**
   * Sign a Solana transaction with the user's wallet. Singular and
   * sign-only — apps submit the returned signed tx through their own
   * RPC. The host doesn't decode or broadcast Solana txs.
   *
   * `payload.unsignedTx` is base64 of `VersionedTransaction.serialize()`
   * (legacy `Transaction` is also acceptable). Implementations should
   * try the versioned-tx path first and fall back to legacy on
   * deserialization failure, mirroring what wallet adapters do.
   *
   * Optional like `signTypedData` — adapters that don't support Solana
   * (e.g. base-account) leave it undefined; `RuntimeTxHandler` rejects
   * the request with a "Solana wallet provider is not ready" error in
   * that case.
   */
  signSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signedTx: string }>;
  signSolanaMessage?: (
    payload: WalletSolanaSignMessagePayload,
  ) => Promise<{ signature: string }>;
  sendSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signature: string; signedTx?: string }>;
  signAndSendSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signature: string; signedTx?: string }>;
  /**
   * Return an upstream wallet-provider credential that the portal can exchange
   * for a short-lived Aomi bearer.
   */
  getAccountCredential?: () => Promise<AomiAccountCredential | null>;
  getAccountBearer?: import("@aomi-labs/client").GetAccountBearer;
  solanaRpcHttpUrl?: string;
  solanaRpcWsUrl?: string;
};

/**
 * Read an environment variable defensively.
 *
 * The value is supplied through a thunk so the literal `process.env.X`
 * reference stays in the source — Next.js still inlines `NEXT_PUBLIC_*` vars at
 * build time — while the try/catch tolerates `process` being undefined in
 * pure-browser builds instead of throwing a ReferenceError.
 */
export function safeEnv(read: () => string | undefined): string | undefined {
  try {
    return read();
  } catch {
    return undefined;
  }
}

"use client";

import type {
  AomiSessionIdentity,
  AomiLoginMethod,
  AuthProviderId,
  SessionProvider,
} from "./types";

export const AOMI_SESSION_DISCONNECTED_IDENTITY: AomiSessionIdentity = {
  status: "disconnected",
  isConnected: false,
  address: undefined,
  walletKind: undefined,
  chainId: undefined,
  svmAddress: undefined,
  walletProviderSubject: undefined,
  authMethod: undefined,
  authValue: undefined,
  authVerifiedAt: undefined,
};

export const AOMI_SESSION_BOOTING_IDENTITY: AomiSessionIdentity = {
  status: "booting",
  isConnected: false,
  address: undefined,
  walletKind: undefined,
  chainId: undefined,
  svmAddress: undefined,
  walletProviderSubject: undefined,
  authMethod: undefined,
  authValue: undefined,
  authVerifiedAt: undefined,
};

export function formatWalletAddress(address?: string): string | undefined {
  if (!address) return undefined;
  return `${address.slice(0, 5)}..${address.slice(-2)}`;
}

export function formatWalletProvider(
  provider?: SessionProvider | AuthProviderId,
): string | undefined {
  if (!provider) return undefined;
  const labelMap: Record<string, string> = {
    none: "Wallet",
    para: "Para",
    privy: "Privy",
    baseAccount: "Base Account",
  };
  return labelMap[provider] ?? provider;
}

export function formatAuthMethod(method?: AomiLoginMethod): string | undefined {
  if (!method) return undefined;
  const labelMap: Record<AomiLoginMethod, string> = {
    google: "Google",
    github: "GitHub",
    apple: "Apple",
    facebook: "Facebook",
    x: "X",
    discord: "Discord",
    farcaster: "Farcaster",
    telegram: "Telegram",
    email: "Email",
    phone: "Phone",
    passkey: "Passkey",
    wallet: "Wallet",
    wagmi: "External Wallet",
  };
  return labelMap[method];
}

const OAUTH_METHODS: ReadonlySet<AomiLoginMethod> = new Set<AomiLoginMethod>([
  "google",
  "apple",
  "facebook",
  "x",
  "discord",
  "github",
  "farcaster",
  "telegram",
  "email",
  "phone",
]);

export function inferAuthMethod(
  authMethods: unknown,
): AomiLoginMethod | undefined {
  if (!(authMethods instanceof Set) || authMethods.size === 0) return undefined;

  for (const method of authMethods) {
    if (typeof method !== "string") continue;
    const normalized = method.toLowerCase();
    if (OAUTH_METHODS.has(normalized as AomiLoginMethod)) {
      return normalized as AomiLoginMethod;
    }
  }
  return undefined;
}

"use client";

import type { PublicWalletFamily, WalletFamily } from "./types";

export function normalizeWalletAddress(
  family: WalletFamily,
  address: string,
): string {
  const trimmed = address.trim();
  return family === "evm" ? trimmed.toLowerCase() : trimmed;
}

export function walletKey(family: WalletFamily, address: string): string {
  return `${family}:${normalizeWalletAddress(family, address)}`;
}

export function toRegistryFamily(
  family: PublicWalletFamily | undefined,
  fallback: WalletFamily = "evm",
): WalletFamily {
  if (!family) return fallback;
  return family;
}

"use client";

import { formatWalletAddress } from "./identity";
import type { AomiAccount } from "./types";
import { walletKey } from "./wallet-utils";
import type { AccountWallet } from "./account/types";

export type EvmConnectionInput = {
  id: string;
  walletName: string;
  address: string;
  chainId?: number;
  provider?: string;
  walletKind?: AomiAccount["walletKind"];
};

export type SvmConnectionInput = {
  id?: string;
  publicKey: string;
  walletName?: string;
  provider?: string;
  walletKind?: AomiAccount["walletKind"];
};

const GENERIC_WALLET_NAMES = new Set(["", "injected", "browser wallet", "wallet"]);

/** A real brand name beats a generic injected label when picking the display row. */
function isRealBrandName(name: string | undefined): boolean {
  return !GENERIC_WALLET_NAMES.has((name ?? "").trim().toLowerCase());
}

export function buildAccounts(input: {
  evmConnections: readonly EvmConnectionInput[];
  activeEvmAddress?: string;
  activeEvmConnectionId?: string;
  svmConnections?: readonly SvmConnectionInput[];
  activeSvmAddress?: string;
}): AomiAccount[] {
  const accounts: AomiAccount[] = [];
  const active = input.activeEvmAddress
    ? walletKey("evm", input.activeEvmAddress)
    : undefined;
  const activeConnId = input.activeEvmConnectionId;

  // Group EVM connections by lowercased address so one address yields one row,
  // regardless of how many connectors expose it (e.g. Rabby impersonating
  // MetaMask via EIP-6963). Preserve first-seen order.
  const evmGroups = new Map<string, EvmConnectionInput[]>();
  for (const conn of input.evmConnections) {
    const key = walletKey("evm", conn.address);
    const group = evmGroups.get(key);
    if (group) group.push(conn);
    else evmGroups.set(key, [conn]);
  }

  for (const [lowerAddr, conns] of evmGroups) {
    const activeConn = activeConnId
      ? conns.find((c) => c.id === activeConnId)
      : undefined;
    const display =
      activeConn ??
      conns.find((c) => isRealBrandName(c.walletName)) ??
      conns[0];
    const isActive = activeConnId
      ? conns.some((c) => c.id === activeConnId)
      : !!active && lowerAddr === active;

    accounts.push({
      id: (activeConn ?? display).id,
      family: "evm",
      address: display.address,
      label: formatWalletAddress(display.address),
      walletName: display.walletName,
      chainId: display.chainId,
      provider: display.provider,
      walletKind: display.walletKind,
      connectorIds: conns.map((c) => c.id),
      active: isActive,
    });
  }

  const seenSvm = new Set<string>();
  for (const connection of input.svmConnections ?? []) {
    const key = walletKey("svm", connection.publicKey);
    if (seenSvm.has(key)) continue;
    seenSvm.add(key);
    accounts.push({
      id: connection.id ?? connection.walletName ?? connection.publicKey,
      family: "svm",
      address: connection.publicKey,
      label: formatWalletAddress(connection.publicKey),
      walletName: connection.walletName,
      provider: connection.provider,
      walletKind: connection.walletKind,
      active: connection.publicKey === input.activeSvmAddress,
    });
  }

  return accounts;
}

export function buildWalletKitAccounts({
  accounts,
  accountWallets = [],
  transformAccounts,
  canManageAccount,
}: {
  accounts: AomiAccount[];
  accountWallets?: readonly AccountWallet[];
  transformAccounts?: (accounts: AomiAccount[]) => AomiAccount[];
  canManageAccount?: (account: AomiAccount) => boolean;
}): AomiAccount[] {
  const linked = applyStoredWalletLinks(accounts, accountWallets);
  const transformed = transformAccounts ? transformAccounts(linked) : linked;
  if (!canManageAccount) return transformed;
  return transformed.map((account) =>
    canManageAccount(account) ? { ...account, manageable: true } : account,
  );
}

function applyStoredWalletLinks(
  accounts: AomiAccount[],
  wallets: readonly AccountWallet[],
): AomiAccount[] {
  if (wallets.length === 0) return accounts;
  const storedByKey = new Map(
    wallets.map((wallet) => [walletKey(wallet.family, wallet.address), wallet]),
  );
  return accounts.map((account) => {
    const stored = storedByKey.get(walletKey(account.family, account.address));
    if (!stored) return account;
    return {
      ...account,
      linked: true,
      linkedVia: stored.linkedVia,
      capability: stored.capability,
    };
  });
}

"use client";

import type { Chain, Transport } from "viem";
import { http } from "viem";
import {
  createConfig,
  createStorage,
  type Config,
  type CreateConnectorFn,
} from "wagmi";
import {
  baseAccount,
  coinbaseWallet,
  injected,
  walletConnect,
} from "wagmi/connectors";
import type { EvmWalletId, EvmWalletPreset } from "./wallet-ids";
import { EVM_PRESETS } from "./wallet-ids";
import { safeEnv } from "../env";

export const AOMI_DEFAULT_WC_PROJECT_ID =
  safeEnv(() => process.env.NEXT_PUBLIC_AOMI_WC_PROJECT_ID) ??
  safeEnv(() => process.env.NEXT_PUBLIC_WALLETCONNECT_PROJECT_ID) ??
  safeEnv(() => process.env.NEXT_PUBLIC_PROJECT_ID);

const evmConfigCache = new Map<string, Config>();

export type ResolvedEvmWalletsConfig = {
  chains: readonly [Chain, ...Chain[]];
  preset?: EvmWalletPreset;
  wallets?: readonly EvmWalletId[];
  connectors?: readonly CreateConnectorFn[];
  walletConnectProjectId?: string;
  coinbase?: boolean;
  appName?: string;
  appLogoUrl?: string | null;
  transports?: Record<number, Transport>;
  ssr?: boolean;
  includeBaseAccount?: boolean;
  persistConnections?: boolean;
};

function defaultHttpTransports(
  chains: readonly Chain[],
): Record<number, Transport> {
  return Object.fromEntries(
    chains.map((chain) => [chain.id, http(chain.rpcUrls.default.http[0])]),
  );
}

function connectorLooksLikeWalletConnect(
  connector: CreateConnectorFn,
): boolean {
  const meta = connector as unknown as {
    id?: string;
    name?: string;
    type?: string;
  };
  const text = [meta.id, meta.name, meta.type].filter(Boolean).join(" ");
  return /wallet\s*connect|walletconnect/i.test(text);
}

function warnDuplicateWalletConnect(): void {
  if (safeEnv(() => process.env.NODE_ENV) === "production") return;
  console.warn(
    "[aomi-wallet-kit] wallets.evm.connectors included a WalletConnect-like connector. Aomi owns the WalletConnect connector; pass walletConnectProjectId instead.",
  );
}

function memoryStringStorage() {
  const store = new Map<string, string>();
  return {
    getItem: (key: string) => store.get(key) ?? null,
    setItem: (key: string, value: string) => {
      store.set(key, value);
    },
    removeItem: (key: string) => {
      store.delete(key);
    },
  };
}

export function createAomiEvmConfig(input: ResolvedEvmWalletsConfig): Config {
  const wanted = new Set(
    input.wallets ?? EVM_PRESETS[input.preset ?? "popular"],
  );
  const wcProjectId =
    input.walletConnectProjectId ?? AOMI_DEFAULT_WC_PROJECT_ID;
  const hostConnectors = (input.connectors ?? []).filter((connector) => {
    if (!connectorLooksLikeWalletConnect(connector)) return true;
    warnDuplicateWalletConnect();
    return false;
  });
  const cacheKey = evmConfigCacheKey(input, wanted, wcProjectId);
  if (cacheKey) {
    const cached = evmConfigCache.get(cacheKey);
    if (cached) return cached;
  }

  const connectors: CreateConnectorFn[] = [
    injected({ shimDisconnect: true }),
    ...(wanted.has("walletconnect") && wcProjectId
      ? [walletConnect({ projectId: wcProjectId, showQrModal: true })]
      : []),
    ...(input.coinbase !== false && wanted.has("coinbase")
      ? [
          coinbaseWallet({
            appName: input.appName ?? "Aomi",
            appLogoUrl: input.appLogoUrl ?? undefined,
          }),
        ]
      : []),
    ...(wanted.has("baseAccount") || input.includeBaseAccount
      ? [
          baseAccount({
            appName: input.appName ?? "Aomi",
            appLogoUrl: input.appLogoUrl ?? null,
            paymasterUrls: {},
          }),
        ]
      : []),
    ...hostConnectors,
  ];

  const config = createConfig({
    chains: input.chains,
    connectors,
    transports: input.transports ?? defaultHttpTransports(input.chains),
    multiInjectedProviderDiscovery: true,
    ssr: input.ssr ?? true,
    // Non-persistent mode still needs a real storage object: WagmiProvider
    // unconditionally calls the persister's rehydrate hook, and `storage: null`
    // leaves it undefined (uncaught error on mount). Memory-backed storage
    // keeps hydration working while nothing survives a reload.
    storage:
      input.persistConnections === false
        ? createStorage({ storage: memoryStringStorage() })
        : undefined,
  });
  if (cacheKey) {
    evmConfigCache.set(cacheKey, config);
    if (evmConfigCache.size > 8) {
      const firstKey = evmConfigCache.keys().next().value;
      if (firstKey) evmConfigCache.delete(firstKey);
    }
  }
  return config;
}

export { EVM_PRESETS };

function evmConfigCacheKey(
  input: ResolvedEvmWalletsConfig,
  wanted: ReadonlySet<EvmWalletId>,
  wcProjectId: string | undefined,
): string | null {
  if (input.connectors?.length || input.transports) return null;
  return JSON.stringify({
    chains: input.chains.map((chain) => [
      chain.id,
      chain.rpcUrls.default.http[0],
    ]),
    wallets: [...wanted].sort(),
    walletConnectProjectId: wcProjectId ?? null,
    coinbase: input.coinbase !== false,
    appName: input.appName ?? null,
    appLogoUrl: input.appLogoUrl ?? null,
    ssr: input.ssr ?? true,
    includeBaseAccount: input.includeBaseAccount ?? false,
    persistConnections: input.persistConnections !== false,
  });
}

