export type AomiBackendAccountEndpointConfig = Partial<{
  accountPath: string;
  signOutPath: string;
  existingSessionProviderExchangePath: string;
  newSessionProviderExchangePath: string;
  walletLinkPath: string;
  walletPath: (walletId: string) => string;
  identityPath: (identityId: string) => string;
  siweNoncePath: string;
  siweVerifyPath: string;
  siwsNoncePath: string;
  siwsVerifyPath: string;
}>;

const DEFAULT_ENDPOINTS = {
  accountPath: "/api/aomi/account",
  signOutPath: "/api/aomi/sign-out",
  existingSessionProviderExchangePath: "/api/aomi/provider/exchange",
  newSessionProviderExchangePath: "/api/auth/aomi/provider/exchange",
  walletLinkPath: "/api/aomi/wallets/link",
  walletPath: (walletId: string) =>
    `/api/aomi/wallets/${encodeURIComponent(walletId)}`,
  identityPath: (identityId: string) =>
    `/api/aomi/identities/${encodeURIComponent(identityId)}`,
  siweNoncePath: "/api/auth/siwe/nonce",
  siweVerifyPath: "/api/auth/siwe/verify",
  siwsNoncePath: "/api/auth/siws/nonce",
  siwsVerifyPath: "/api/auth/siws/verify",
} satisfies Required<AomiBackendAccountEndpointConfig>;

export function createAomiBackendAccountClient(input: {
  baseUrl?: string;
  endpoints?: AomiBackendAccountEndpointConfig;
  fetch?: typeof fetch;
  auth?: AomiBackendAccountAuth;
}) {
  const baseUrl = normalizeBaseUrl(input.baseUrl);
  const fetchImpl = input.fetch ?? fetch;
  const endpoints = { ...DEFAULT_ENDPOINTS, ...(input.endpoints ?? {}) };
  const auth = input.auth ?? { credentials: "include" as const };

  const urlFor = (path: string) => `${baseUrl}${path}`;
  // `request` is for endpoints that always return a JSON body; `requestVoid` is
  // for no-content mutations. Keeping them separate lets each return an honest
  // type instead of casting an empty response to `T`.
  const request = <T>(path: string, init: RequestInit) =>
    fetchJson<T>(fetchImpl, urlFor(path), init, auth);
  const requestVoid = (path: string, init: RequestInit) =>
    fetchVoid(fetchImpl, urlFor(path), init, auth);

  return {
    getAccount: () =>
      request<AomiBackendAccountResponse>(endpoints.accountPath, {
        method: "GET",
      }),
    updateAccount: (body: {
      displayName?: string | null;
      avatarUrl?: string | null;
    }) =>
      request<AomiBackendAccountResponse>(endpoints.accountPath, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    deleteAccount: () =>
      request<AomiBackendDeleteAccountResponse>(endpoints.accountPath, {
        method: "DELETE",
      }),
    signOut: () => requestVoid(endpoints.signOutPath, { method: "POST" }),
    exchangeProviderCredential: (
      credential: AomiAccountCredential,
      options: { hasAccount: boolean },
    ) =>
      request<AomiBackendProviderExchangeResponse>(
        options.hasAccount
          ? endpoints.existingSessionProviderExchangePath
          : endpoints.newSessionProviderExchangePath,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(credential),
        },
      ),
    getWalletLinkNonce: (input: { address: string; chainId: number }) => {
      const params = new URLSearchParams({
        address: input.address,
        chainId: String(input.chainId),
      });
      return request<AomiBackendNonceResponse>(
        `${endpoints.walletLinkPath}?${params.toString()}`,
        { method: "GET" },
      );
    },
    linkWallet: (body: unknown) =>
      request<AomiBackendLinkWalletResponse>(endpoints.walletLinkPath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    updateWallet: (walletId: string, body: { label?: string | null }) =>
      requestVoid(endpoints.walletPath(walletId), {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    updateAuthIdentity: (
      identityId: string,
      body: { displayLabel?: string | null },
    ) =>
      requestVoid(endpoints.identityPath(identityId), {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    unlinkWallet: (walletId: string) =>
      requestVoid(endpoints.walletPath(walletId), { method: "DELETE" }),
    unlinkAuthIdentity: (identityId: string) =>
      requestVoid(endpoints.identityPath(identityId), { method: "DELETE" }),
    createSiweNonce: (body: { walletAddress: string; chainId: number }) =>
      request<AomiBackendNonceResponse>(endpoints.siweNoncePath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    verifySiwe: (body: {
      message: string;
      signature: string;
      walletAddress: string;
      chainId: number;
    }) =>
      requestVoid(endpoints.siweVerifyPath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    createSiwsNonce: (body: {
      walletAddress: string;
      chainId: SvmCluster;
      intent: "sign-in" | "link";
    }) =>
      request<AomiBackendNonceResponse>(endpoints.siwsNoncePath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
    verifySiws: (body: {
      message: string;
      signature: string;
      walletAddress: string;
      chainId: SvmCluster;
      intent: "sign-in" | "link";
      label?: string;
    }) =>
      requestVoid(endpoints.siwsVerifyPath, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      }),
  };
}

async function sendAccountRequest(
  fetchImpl: typeof fetch,
  url: string,
  init: RequestInit,
  auth: AomiBackendAccountAuth,
): Promise<Response> {
  const execute = async (forceRefresh: boolean) => {
    const headers = new Headers(init.headers);
    headers.set("Accept", "application/json");
    if (auth.credentials === "omit") {
      const authorization = await auth.getAuthorization({ forceRefresh });
      if (!authorization)
        throw new Error("Widget authorization is unavailable");
      headers.set("Authorization", `Bearer ${authorization}`);
    }
    return fetchImpl(url, {
      ...init,
      credentials: auth.credentials ?? "include",
      headers,
    });
  };
  let response = await execute(false);
  if (response.status === 401 && auth.credentials === "omit") {
    response = await execute(true);
  }
  if (!response.ok) {
    const error = await response.json().catch(() => null);
    const code = extractErrorCode(error);
    throw new AomiAccountRequestError(
      response.status,
      code,
      extractConflictSignal(error),
    );
  }
  return response;
}

async function fetchJson<T>(
  fetchImpl: typeof fetch,
  url: string,
  init: RequestInit,
  auth: AomiBackendAccountAuth,
): Promise<T> {
  const response = await sendAccountRequest(fetchImpl, url, init, auth);
  // These endpoints always return a JSON body on success; an empty response is
  // a contract violation, so surface it instead of casting `undefined` to `T`.
  if (response.status === 204 || response.status === 205) {
    throw new Error("Account request returned no content");
  }
  const body = await response.text();
  if (!body.trim()) {
    throw new Error("Account request returned an empty body");
  }
  return JSON.parse(body) as T;
}

async function fetchVoid(
  fetchImpl: typeof fetch,
  url: string,
  init: RequestInit,
  auth: AomiBackendAccountAuth,
): Promise<void> {
  await sendAccountRequest(fetchImpl, url, init, auth);
}

function extractErrorCode(error: unknown): string | null {
  if (!error || typeof error !== "object") return null;
  if ("error" in error && error.error) return String(error.error);
  if ("message" in error && error.message) return String(error.message);
  return null;
}

function extractConflictSignal(
  error: unknown,
): AomiAccountConflictSignal | null {
  if (!error || typeof error !== "object" || !("signalType" in error)) {
    return null;
  }
  const value = (error as { signalType: unknown }).signalType;
  return value === "wallet" || value === "identity" || value === "email"
    ? value
    : null;
}

const CONFLICT_MESSAGES: Record<AomiAccountConflictSignal, string> = {
  wallet:
    "This wallet address is already linked to another Aomi account. Sign in to that account, unlink the wallet there, then return here and link it.",
  identity:
    "This sign-in method is already linked to another Aomi account. Sign in to that account, unlink it there, then return here and link it.",
  email:
    "This email is already linked to another Aomi account. Sign in to that account, unlink it there, then return here and link it.",
};

function formatAccountRequestError(
  status: number,
  code: string | null,
  signalType: AomiAccountConflictSignal | null,
): string {
  if (status === 409 && code === "already_linked_to_another_account") {
    return (
      (signalType ? CONFLICT_MESSAGES[signalType] : undefined) ??
      "This wallet or sign-in method is already linked to another Aomi account. Sign in to that account, unlink it there, then return here and link it."
    );
  }
  return code ?? `Request failed: ${status}`;
}

function normalizeBaseUrl(baseUrl?: string): string {
  return baseUrl?.replace(/\/+$/, "") ?? "";
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { buildSiwsMessage } from "@aomi-labs/client";
import type { AuthRuntime, SvmWalletRuntime } from "../composer/types";
import type { EvmWalletRuntime } from "../runtime/evm/wallet-runtime";
import { brandDisplayName } from "../runtime/evm/brands";
import type { AccountRuntime, AccountWallet } from "./types";
import type { AomiAccount, SvmCluster, WalletFamily } from "../types";
import {
  AomiAccountRequestError,
  createAomiBackendAccountClient,
  type AomiBackendAccountResponse,
  type AomiBackendNonceResponse,
} from "./aomi-backend-client";
import {
  useAccountSessionProvider,
  widgetCredentialsReady,
  type WidgetAuthConfig,
} from "./use-widget-session-provider";
import { utf8ToBase64 } from "./encoding";

export type AomiBackendAccountConfig = {
  mode: "aomi-backend";
  baseUrl?: string;
  authDomain?: string;
  authUri?: string;
  widgetAuth?: WidgetAuthConfig;
};

const CREDENTIAL_EXCHANGE_FAILURE_COOLDOWN_MS = 30_000;

export function useAomiBackendAccountRuntime(input: {
  enabled: boolean;
  baseUrl?: string;
  authDomain?: string;
  authUri?: string;
  widgetAuth?: AomiBackendAccountConfig["widgetAuth"];
  auth: AuthRuntime;
  evm: EvmWalletRuntime;
  svm?: SvmWalletRuntime;
}): AccountRuntime {
  const accountSessionProvider = useAccountSessionProvider({
    baseUrl: input.baseUrl,
    widgetAuth: input.widgetAuth,
    auth: input.auth,
    evm: input.evm,
    svm: input.svm,
  });
  const accountClient = useMemo(
    () =>
      createAomiBackendAccountClient({
        baseUrl: input.baseUrl,
        auth: accountSessionProvider
          ? { credentials: "omit", getAuthorization: accountSessionProvider }
          : { credentials: "include" },
      }),
    [input.baseUrl, accountSessionProvider],
  );
  const authMessageConfig = useMemo(
    () =>
      resolveAuthMessageConfig({
        baseUrl: input.baseUrl,
        authDomain: input.authDomain,
        authUri: input.authUri,
      }),
    [input.authDomain, input.authUri, input.baseUrl],
  );
  // Widget mode is signed-out/idle (not an error) until it has a usable
  // credential source. Provider mode: authenticated + exchangeable credential.
  // Wallet mode: a connected external wallet that can sign. Both layers share
  // `widgetCredentialsReady` so the runtime and the provider builder agree.
  const widgetSignedOut =
    Boolean(input.widgetAuth) &&
    !widgetCredentialsReady({
      widgetAuth: input.widgetAuth as WidgetAuthConfig,
      authStatus: input.auth.status,
      hasAuthCredential: Boolean(input.auth.getCredential),
      evm: input.evm,
      svm: input.svm,
    });
  const [account, setAccount] = useState<AomiBackendAccountResponse | null>(
    null,
  );
  const [status, setStatus] = useState<AccountRuntime["status"]>(
    input.enabled ? (widgetSignedOut ? "ready" : "loading") : "disabled",
  );
  const [errorVersion, setErrorVersion] = useState(0);
  const [accountError, setAccountError] = useState<string | undefined>();
  const refreshContextKey = JSON.stringify([
    input.enabled,
    input.widgetAuth?.mode ?? "native",
    input.widgetAuth?.mode === "provider" ? input.widgetAuth.provider : "",
    input.widgetAuth?.mode === "provider" ? input.widgetAuth.environment : "",
    input.auth.status,
    input.auth.provider,
    input.auth.subject ?? "",
    input.evm.activeEvmConnection?.address ?? "",
    input.evm.activeEvmConnection?.chainId ?? "",
    input.svm?.identity(Date.now())?.address ?? "",
    input.svm?.selectedNetwork?.cluster ?? "",
  ]);
  const latestRefreshContext = useRef({ accountClient, refreshContextKey });
  latestRefreshContext.current = { accountClient, refreshContextKey };
  const refreshInFlight = useRef<{
    accountClient: typeof accountClient;
    contextKey: string;
    promise: Promise<void>;
  } | null>(null);
  const siweInFlight = useRef<string | null>(null);
  const siwsInFlight = useRef<string | null>(null);
  const walletLabelSyncInFlight = useRef<string | null>(null);
  const accountCreateInFlight = useRef<string | null>(null);
  const signedOutEvmKey = useRef<string | null>(null);
  const signedOutSvmKey = useRef<string | null>(null);
  const signedOutCredentialKey = useRef<string | null>(null);
  const credentialInFlight = useRef<string | null>(null);
  const credentialExchanged = useRef<string | null>(null);
  const providerSessionAttempted = useRef<string | null>(null);
  const credentialFailed = useRef<{
    attemptKey: string;
    failedAt: number;
  } | null>(null);

  const refresh = useCallback(async () => {
    if (!input.enabled) return;
    // Widget mode cannot mint a WST before it has a usable credential source
    // (provider: host login; wallet: a connected external signer). Treat that
    // as the normal signed-out state instead of asking the account client for
    // authorization and surfacing a boot error.
    if (widgetSignedOut) {
      refreshInFlight.current = null;
      setAccount(null);
      setStatus("ready");
      return;
    }
    // Two mount effects both trigger the initial fetch; coalesce concurrent
    // calls for the same principal/client onto one in-flight promise.
    const existing = refreshInFlight.current;
    if (
      existing?.accountClient === accountClient &&
      existing.contextKey === refreshContextKey
    ) {
      return existing.promise;
    }
    const entry: NonNullable<typeof refreshInFlight.current> = {
      accountClient,
      contextKey: refreshContextKey,
      promise: Promise.resolve(),
    };
    const run = (async () => {
      setStatus((current) => (current === "ready" ? current : "loading"));
      // Let the entry become visible before invoking the client, including if a
      // test double or future client implementation throws synchronously.
      await Promise.resolve();
      try {
        const next = await accountClient.getAccount();
        const latest = latestRefreshContext.current;
        if (
          latest.accountClient !== accountClient ||
          latest.refreshContextKey !== refreshContextKey
        ) {
          return;
        }
        setAccount(next);
        setStatus("ready");
      } catch {
        const latest = latestRefreshContext.current;
        if (
          latest.accountClient !== accountClient ||
          latest.refreshContextKey !== refreshContextKey
        ) {
          return;
        }
        setStatus("error");
        setErrorVersion((version) => version + 1);
      } finally {
        if (refreshInFlight.current === entry) {
          refreshInFlight.current = null;
        }
      }
    })();
    entry.promise = run;
    refreshInFlight.current = entry;
    return run;
  }, [accountClient, input.enabled, refreshContextKey, widgetSignedOut]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (input.auth.status !== "authenticated") {
      signedOutCredentialKey.current = null;
      credentialInFlight.current = null;
      credentialExchanged.current = null;
      providerSessionAttempted.current = null;
      credentialFailed.current = null;
      setAccountError(undefined);
    }
  }, [input.auth.status, input.auth.subject]);

  const activeEvmAddress =
    input.evm.activeEvmConnection?.address ?? input.evm.activeAccount?.address;
  const activeEvmChainId =
    input.evm.activeEvmConnection?.chainId ?? input.evm.activeAccount?.chainId;
  const activeEvmWalletName = activeEvmAddress
    ? resolveLinkedWalletName({
        accounts: input.evm.accounts(Date.now()),
        accountId: input.evm.activeAccount?.id,
        address: activeEvmAddress,
        fallbackWalletName:
          input.evm.activeAccount?.walletName ??
          input.evm.activeEvmConnection?.walletName,
      })
    : undefined;
  const activeSvmIdentity = input.svm?.identity(Date.now());
  const activeSvmAccount = input.svm?.activeAccount;
  const activeSvmAddress =
    activeSvmAccount?.address ?? activeSvmIdentity?.address;
  const activeSvmCluster =
    input.svm?.selectedNetwork?.cluster ??
    activeSvmIdentity?.cluster ??
    "solana:mainnet";
  const activeSvmWalletName =
    activeSvmAccount?.walletName ?? activeSvmIdentity?.walletName;
  const activeSvmIsExternal = Boolean(
    activeSvmAddress &&
    activeSvmAccount?.walletKind !== "embedded" &&
    activeSvmAccount?.walletKind !== "smart_account" &&
    activeSvmIdentity?.transport !== "embedded" &&
    activeSvmIdentity?.walletSource !== "embedded",
  );
  const signSolanaMessage = input.svm?.execution.signSolanaMessage;

  useEffect(() => {
    if (input.widgetAuth) void refresh();
  }, [
    activeEvmAddress,
    activeSvmAddress,
    input.auth.status,
    input.auth.subject,
    input.widgetAuth?.mode,
    refresh,
  ]);

  useEffect(() => {
    if (!account?.user || !activeEvmAddress) return;
    const brand = brandDisplayName(activeEvmWalletName);
    if (brand === "Wallet") return;
    const wallet = account.wallets.find(
      (candidate) =>
        candidate.family === "evm" &&
        candidate.address.toLowerCase() === activeEvmAddress.toLowerCase() &&
        !candidate.label?.trim(),
    );
    if (!wallet) return;
    const label = buildDefaultWalletLabel({
      walletName: brand,
      existingWallets: account.wallets,
      family: "evm",
    });
    const key = `${wallet.id}:${label}`;
    if (walletLabelSyncInFlight.current === key) return;
    walletLabelSyncInFlight.current = key;
    accountClient
      .updateWallet(wallet.id, { label })
      .then(refresh)
      .catch(() => setErrorVersion((version) => version + 1))
      .finally(() => {
        if (walletLabelSyncInFlight.current === key) {
          walletLabelSyncInFlight.current = null;
        }
      });
  }, [account, accountClient, activeEvmAddress, activeEvmWalletName, refresh]);

  useEffect(() => {
    if (
      !input.enabled ||
      Boolean(input.widgetAuth) ||
      status === "error" ||
      account === null ||
      account.user ||
      !hasAuthMessageConfig(authMessageConfig)
    ) {
      return;
    }
    if (!activeEvmAddress || !activeEvmChainId || !input.evm.signMessageAsync) {
      signedOutEvmKey.current = null;
      return;
    }
    const key = `${activeEvmAddress}:${activeEvmChainId}`;
    const authKey = authSessionKey(input.auth);
    if (
      input.auth.status === "authenticated" &&
      input.auth.getCredential &&
      providerSessionAttempted.current !== authKey
    ) {
      return;
    }
    if (signedOutEvmKey.current === key) return;
    if (siweInFlight.current === key) return;
    if (accountCreateInFlight.current) return;
    siweInFlight.current = key;
    accountCreateInFlight.current = `siwe:${key}`;
    signInWithActiveEvmWallet({
      address: activeEvmAddress as `0x${string}`,
      accountClient,
      chainId: activeEvmChainId,
      signMessageAsync: input.evm.signMessageAsync as (args: {
        message: string;
      }) => Promise<`0x${string}`>,
      messageConfig: authMessageConfig,
    })
      .then(refresh)
      .catch(() => {
        // A rejected/failed auto-SIWE attempt must not block provider-token
        // sign-in; suppress repeat prompts for this wallet and keep runtime live.
        signedOutEvmKey.current = key;
        setStatus("ready");
        setErrorVersion((version) => version + 1);
      })
      .finally(() => {
        siweInFlight.current = null;
        if (accountCreateInFlight.current === `siwe:${key}`) {
          accountCreateInFlight.current = null;
        }
      });
  }, [
    account,
    activeEvmAddress,
    activeEvmChainId,
    accountClient,
    authMessageConfig,
    input.enabled,
    input.evm.signMessageAsync,
    refresh,
    status,
  ]);

  useEffect(() => {
    if (
      !input.enabled ||
      Boolean(input.widgetAuth) ||
      status === "error" ||
      account === null ||
      account.user ||
      !hasAuthMessageConfig(authMessageConfig)
    ) {
      return;
    }
    if (!activeSvmAddress || !activeSvmIsExternal || !signSolanaMessage) {
      signedOutSvmKey.current = null;
      return;
    }
    const key = `${activeSvmAddress}:${activeSvmCluster}`;
    const authKey = authSessionKey(input.auth);
    if (
      input.auth.status === "authenticated" &&
      input.auth.getCredential &&
      providerSessionAttempted.current !== authKey
    ) {
      return;
    }
    if (signedOutSvmKey.current === key) return;
    if (siwsInFlight.current === key) return;
    if (accountCreateInFlight.current) return;
    siwsInFlight.current = key;
    accountCreateInFlight.current = `siws:${key}`;
    authenticateSvmWallet({
      accountClient,
      address: activeSvmAddress,
      chainId: activeSvmCluster,
      intent: "sign-in",
      label: buildDefaultWalletLabel({
        walletName: activeSvmWalletName,
        existingWallets: [],
        family: "svm",
      }),
      messageConfig: authMessageConfig,
      signMessage: (message) =>
        signMessageWithActiveSvm(signSolanaMessage, message, activeSvmCluster),
    })
      .then(refresh)
      .catch(() => {
        // Match auto-SIWE: one rejected prompt should not loop until the wallet
        // disconnects or the user explicitly chooses Link again.
        signedOutSvmKey.current = key;
        setStatus("ready");
        setErrorVersion((version) => version + 1);
      })
      .finally(() => {
        siwsInFlight.current = null;
        if (accountCreateInFlight.current === `siws:${key}`) {
          accountCreateInFlight.current = null;
        }
      });
  }, [
    account,
    accountClient,
    activeSvmAddress,
    activeSvmCluster,
    activeSvmIsExternal,
    activeSvmWalletName,
    authMessageConfig,
    input.auth,
    input.enabled,
    refresh,
    signSolanaMessage,
    status,
  ]);

  useEffect(() => {
    if (
      !input.enabled ||
      Boolean(input.widgetAuth) ||
      status === "error" ||
      input.auth.status !== "authenticated"
    ) {
      return;
    }
    if (!input.auth.getCredential) return;
    let cancelled = false;
    async function exchange() {
      const authKey = authSessionKey(input.auth);
      const credential = await input.auth.getCredential?.().catch(() => null);
      if (!credential || cancelled) {
        if (!cancelled) providerSessionAttempted.current = authKey;
        return;
      }
      const key = credentialKey(credential);
      const signedOutKey = authCredentialKey(input.auth, key);
      if (!account?.user && signedOutCredentialKey.current === signedOutKey) {
        providerSessionAttempted.current = authKey;
        return;
      }
      // Any provider credential is exchangeable, in any order: link to the
      // current account if one exists, otherwise create one. No policy gate.
      const hasAccount = Boolean(account?.user);
      const attemptKey = `${hasAccount ? "link" : "session"}:${account?.user?.id ?? "new"}:${key}`;
      if (!hasAccount && accountCreateInFlight.current) return;
      const failedAttempt = credentialFailed.current;
      if (
        credentialInFlight.current === attemptKey ||
        credentialExchanged.current === attemptKey ||
        (failedAttempt?.attemptKey === attemptKey &&
          Date.now() - failedAttempt.failedAt <
            CREDENTIAL_EXCHANGE_FAILURE_COOLDOWN_MS)
      ) {
        return;
      }
      credentialInFlight.current = attemptKey;
      if (!hasAccount) accountCreateInFlight.current = attemptKey;
      try {
        setAccountError(undefined);
        const result = await accountClient.exchangeProviderCredential(
          credential,
          { hasAccount },
        );
        credentialExchanged.current = attemptKey;
        if (result.account) setAccount(result.account);
        await refresh();
      } catch (error) {
        credentialFailed.current = { attemptKey, failedAt: Date.now() };
        if (
          error instanceof AomiAccountRequestError &&
          error.status === 409 &&
          error.code === "already_linked_to_another_account"
        ) {
          setAccountError(error.message);
        }
        setStatus("ready");
        setErrorVersion((version) => version + 1);
      } finally {
        providerSessionAttempted.current = authKey;
        if (credentialInFlight.current === attemptKey) {
          credentialInFlight.current = null;
        }
        if (accountCreateInFlight.current === attemptKey) {
          accountCreateInFlight.current = null;
        }
      }
    }
    void exchange();
    return () => {
      cancelled = true;
    };
  }, [
    account?.user,
    accountClient,
    input.auth,
    input.enabled,
    refresh,
    status,
  ]);

  const liveAccounts = useMemo(
    () => [
      ...input.evm.accounts(Date.now()),
      ...(input.svm?.accounts(Date.now()) ?? []),
    ],
    // `errorVersion` intentionally re-samples live wallet adapters after a
    // failed auth/account side effect, because the adapter object identities
    // can stay stable while their internal account snapshots changed.
    [errorVersion, input.evm, input.svm],
  );

  const liveWalletKeys = useMemo(() => {
    const keys = new Set<string>();
    for (const acct of liveAccounts) {
      keys.add(walletAccountKey(acct.family, acct.address));
    }
    return keys;
  }, [liveAccounts]);

  const wallets = useMemo(
    () =>
      (account?.wallets ?? []).map((wallet) => {
        const key = walletAccountKey(wallet.family, wallet.address);
        return {
          ...normalizeAccountWalletProvider(wallet, liveAccounts),
          capability: liveWalletKeys.has(key) ? "write" : "read",
        } satisfies AccountWallet;
      }),
    [account?.wallets, liveAccounts, liveWalletKeys],
  );

  return {
    status: input.enabled ? status : "disabled",
    error: accountError,
    user: account?.user ?? undefined,
    linkedAccounts: account?.linkedAccounts ?? [],
    wallets,
    getAccountBearer: accountSessionProvider,
    refresh,
    signOut: async () => {
      if (activeEvmAddress && activeEvmChainId) {
        signedOutEvmKey.current = `${activeEvmAddress}:${activeEvmChainId}`;
      }
      if (activeSvmAddress && activeSvmIsExternal) {
        signedOutSvmKey.current = `${activeSvmAddress}:${activeSvmCluster}`;
      }
      if (
        !input.widgetAuth &&
        input.auth.status === "authenticated" &&
        input.auth.getCredential
      ) {
        const credential = await input.auth.getCredential().catch(() => null);
        if (credential) {
          signedOutCredentialKey.current = authCredentialKey(
            input.auth,
            credentialKey(credential),
          );
        }
      }
      credentialInFlight.current = null;
      credentialExchanged.current = null;
      providerSessionAttempted.current = null;
      credentialFailed.current = null;
      setAccountError(undefined);
      // Revoke the backend account first (while the WST carrier is still
      // valid), but always tear down the widget session / provider SDK even if
      // that first step throws, so a stale WST can't be replayed and the
      // provider SDK session isn't stranded.
      try {
        await accountClient.signOut();
      } finally {
        await accountSessionProvider?.signOut();
      }
      setAccount({
        user: null,
        linkedAccounts: [],
        wallets: [],
        session: null,
      });
      setStatus("ready");
    },
    deleteAccount: async () => {
      if (activeEvmAddress && activeEvmChainId) {
        signedOutEvmKey.current = `${activeEvmAddress}:${activeEvmChainId}`;
      }
      if (activeSvmAddress && activeSvmIsExternal) {
        signedOutSvmKey.current = `${activeSvmAddress}:${activeSvmCluster}`;
      }
      if (
        !input.widgetAuth &&
        input.auth.status === "authenticated" &&
        input.auth.getCredential
      ) {
        const credential = await input.auth.getCredential().catch(() => null);
        if (credential) {
          signedOutCredentialKey.current = authCredentialKey(
            input.auth,
            credentialKey(credential),
          );
        }
      }
      credentialInFlight.current = null;
      credentialExchanged.current = null;
      providerSessionAttempted.current = null;
      credentialFailed.current = null;
      setAccountError(undefined);
      // Mirror signOut: revoke the widget session too so the just-deleted
      // account's cached WST can't be replayed or silently re-minted on a
      // force-refresh. Always run the widget teardown even if delete throws.
      try {
        await accountClient.deleteAccount();
      } finally {
        await accountSessionProvider?.signOut();
      }
      setAccount({
        user: null,
        linkedAccounts: [],
        wallets: [],
        session: null,
      });
      setStatus("ready");
    },
    updateAccount: async ({ displayName, avatarUrl }) => {
      await accountClient.updateAccount({ displayName, avatarUrl });
      await refresh();
    },
    linkWallet: async (wallet) => {
      if (wallet.family === "svm") {
        if (
          !activeSvmAddress ||
          wallet.address !== activeSvmAddress ||
          !activeSvmIsExternal ||
          !signSolanaMessage
        ) {
          throw new Error(
            "Wallet linking requires the active external Solana signer",
          );
        }
        const label = buildDefaultWalletLabel({
          walletName: activeSvmWalletName,
          existingWallets: account?.wallets ?? [],
          family: "svm",
        });
        await authenticateSvmWallet({
          accountClient,
          address: wallet.address,
          chainId: activeSvmCluster,
          intent: account?.user ? "link" : "sign-in",
          label,
          messageConfig: authMessageConfig,
          signMessage: (message) =>
            signMessageWithActiveSvm(
              signSolanaMessage,
              message,
              activeSvmCluster,
            ),
        });
        await refresh();
        return;
      }
      if (!input.evm.signMessageForAccount && !input.evm.signMessageAsync) {
        throw new Error("Wallet linking requires an active EVM signer");
      }
      const chainId = wallet.chainId ?? activeEvmChainId;
      if (!chainId) throw new Error("Wallet linking requires an EVM chain id");
      if (!account?.user) {
        const accountId = wallet.accountId;
        const signMessageForAccount = input.evm.signMessageForAccount;
        await signInWithEvmWallet({
          accountClient,
          address: wallet.address as `0x${string}`,
          chainId,
          signMessage:
            accountId && signMessageForAccount
              ? (message) =>
                  signMessageForAccount({
                    accountId,
                    chainId,
                    message,
                  })
              : (message) =>
                  signMessageWithActiveEvm(input.evm.signMessageAsync, message),
          messageConfig: authMessageConfig,
        });
        await refresh();
        return;
      }
      const nonceResult = await accountClient.getWalletLinkNonce({
        address: wallet.address,
        chainId,
      });
      const message = buildWalletLinkMessage({
        address: wallet.address,
        chainId,
        nonce: nonceResult.nonce,
        ...messageConfigFromNonce(nonceResult, authMessageConfig),
      });
      const signature =
        wallet.accountId && input.evm.signMessageForAccount
          ? await input.evm.signMessageForAccount({
              accountId: wallet.accountId,
              chainId,
              message,
            })
          : await signMessageWithActiveEvm(input.evm.signMessageAsync, message);
      // Name the label after the wallet actually being linked, not whichever
      // wallet happens to be the active EVM signer — linking MetaMask while a
      // Privy smart wallet is active must read "MetaMask N", not "Privy …".
      const defaultLabel = buildDefaultWalletLabel({
        walletName: resolveLinkedWalletName({
          accounts: input.evm.accounts(Date.now()),
          accountId: wallet.accountId,
          address: wallet.address,
          fallbackWalletName: input.evm.activeEvmConnection?.walletName,
        }),
        existingWallets: account?.wallets ?? [],
        family: wallet.family,
      });
      const body = {
        ...wallet,
        chainId,
        label: defaultLabel,
        message,
        signature,
        nonce: nonceResult.nonce,
      };
      const result = await accountClient.linkWallet(body);
      if (result.account) setAccount(result.account);
      await refresh();
    },
    updateWallet: async ({ walletId, label }) => {
      await accountClient.updateWallet(walletId, { label });
      await refresh();
    },
    updateAuthIdentity: async ({ identityId, displayLabel }) => {
      await accountClient.updateAuthIdentity(identityId, { displayLabel });
      await refresh();
    },
    unlinkWallet: async (walletId) => {
      await accountClient.unlinkWallet(walletId);
      await refresh();
    },
    unlinkAuthIdentity: async (identityId) => {
      await accountClient.unlinkAuthIdentity(identityId);
      await refresh();
    },
  };
}

function walletAccountKey(family: WalletFamily, address: string): string {
  return family === "evm"
    ? `${family}:${address.toLowerCase()}`
    : `${family}:${address}`;
}

export function normalizeAccountWalletProvider(
  wallet: AccountWallet,
  liveAccounts: readonly Pick<
    AomiAccount,
    "family" | "address" | "provider" | "walletKind"
  >[],
): AccountWallet {
  const liveAccount = liveAccounts.find(
    (account) =>
      account.family === wallet.family &&
      walletAccountKey(account.family, account.address) ===
        walletAccountKey(wallet.family, wallet.address),
  );
  const provider = liveAccount?.provider;
  const walletKind = liveAccount?.walletKind;
  if (
    provider &&
    walletKind &&
    walletKind !== "embedded" &&
    walletKind !== "smart_account"
  ) {
    return wallet;
  }
  const inferredProvider =
    provider ?? providerLinkedWalletVia(wallet.linkedVia);
  if (!inferredProvider) return wallet;

  return {
    ...wallet,
    provider: wallet.provider ?? inferredProvider,
    kind:
      walletKind === "embedded" || walletKind === "smart_account"
        ? walletKind
        : (wallet.kind ?? "embedded"),
  };
}

function providerLinkedWalletVia(linkedVia: AccountWallet["linkedVia"]) {
  if (
    linkedVia === "siwe" ||
    linkedVia === "siws" ||
    linkedVia === "challenge" ||
    linkedVia === "import" ||
    linkedVia === "observed" ||
    linkedVia === "migration"
  ) {
    return null;
  }
  return linkedVia;
}

function credentialKey(credential: unknown): string {
  return (JSON.stringify(credential) ?? "").slice(0, 96);
}

function authCredentialKey(
  auth: Pick<AuthRuntime, "provider" | "subject">,
  key: string,
): string {
  return `${auth.provider}:${auth.subject ?? "unknown"}:${key}`;
}

function authSessionKey(
  auth: Pick<AuthRuntime, "provider" | "subject">,
): string {
  return `${auth.provider}:${auth.subject ?? "unknown"}`;
}

/**
 * Resolve the brand name of the wallet being linked from the live EVM accounts,
 * matching by stable account id first and address second. Falls back to the
 * caller-supplied active-connection name only when the linked wallet isn't in
 * the live set — so a default label is always brand-correct for the wallet the
 * user actually picked, even when a different wallet is the active signer.
 */
export function resolveLinkedWalletName(input: {
  accounts: ReadonlyArray<{
    id: string;
    address?: string;
    walletName?: string;
  }>;
  accountId?: string;
  address: string;
  fallbackWalletName?: string;
}): string | undefined {
  const target = input.address.toLowerCase();
  const match = input.accounts.find(
    (candidate) =>
      (input.accountId !== undefined && candidate.id === input.accountId) ||
      candidate.address?.toLowerCase() === target,
  );
  return match?.walletName ?? input.fallbackWalletName;
}

/**
 * Build a first-link default label like "Rabby 1" / "MetaMask 2" so the
 * account-management row is never blank before the user renames it. Only used
 * as the initial value — the account service persists labels as
 * `auth_providers.provider_metadata.display_label` and keeps the stored one on
 * re-link, so user renames stick.
 */
export function buildDefaultWalletLabel(input: {
  walletName?: string | null;
  existingWallets: readonly AccountWallet[];
  family: WalletFamily;
}): string {
  const brand = brandDisplayName(input.walletName);
  const sameBrand = input.existingWallets.filter(
    (wallet) =>
      wallet.family === input.family &&
      wallet.label?.toLowerCase().startsWith(brand.toLowerCase()),
  ).length;
  return `${brand} ${sameBrand + 1}`;
}

async function signMessageWithActiveEvm(
  signMessageAsync: EvmWalletRuntime["signMessageAsync"],
  message: string,
): Promise<`0x${string}`> {
  if (!signMessageAsync) {
    throw new Error("Wallet linking requires an active EVM signer");
  }
  return (await (
    signMessageAsync as (args: { message: string }) => Promise<`0x${string}`>
  )({ message })) as `0x${string}`;
}

async function signInWithActiveEvmWallet(input: {
  accountClient: ReturnType<typeof createAomiBackendAccountClient>;
  address: `0x${string}`;
  chainId: number;
  signMessageAsync: (args: { message: string }) => Promise<`0x${string}`>;
  messageConfig: AuthMessageConfig;
}): Promise<void> {
  await signInWithEvmWallet({
    accountClient: input.accountClient,
    address: input.address,
    chainId: input.chainId,
    signMessage: (message) => input.signMessageAsync({ message }),
    messageConfig: input.messageConfig,
  });
}

async function signInWithEvmWallet(input: {
  accountClient: ReturnType<typeof createAomiBackendAccountClient>;
  address: `0x${string}`;
  chainId: number;
  signMessage: (message: string) => Promise<`0x${string}`>;
  messageConfig: AuthMessageConfig;
}): Promise<void> {
  const nonceResult = await input.accountClient.createSiweNonce({
    walletAddress: input.address,
    chainId: input.chainId,
  });
  const message = buildSiweMessage({
    address: input.address,
    chainId: input.chainId,
    nonce: nonceResult.nonce,
    ...messageConfigFromNonce(nonceResult, input.messageConfig),
  });
  const signature = await input.signMessage(message);
  await input.accountClient.verifySiwe({
    message,
    signature,
    walletAddress: input.address,
    chainId: input.chainId,
  });
}

async function signMessageWithActiveSvm(
  signMessage: NonNullable<SvmWalletRuntime["execution"]["signSolanaMessage"]>,
  message: string,
  chainId: SvmCluster,
): Promise<string> {
  const result = await signMessage({
    message: utf8ToBase64(message),
    cluster: chainId,
    description: "Authorize this Solana wallet for your Aomi account.",
  });
  return result.signature;
}

async function authenticateSvmWallet(input: {
  accountClient: ReturnType<typeof createAomiBackendAccountClient>;
  address: string;
  chainId: SvmCluster;
  intent: "sign-in" | "link";
  label?: string;
  signMessage: (message: string) => Promise<string>;
  messageConfig: AuthMessageConfig;
}): Promise<void> {
  const nonceResult = await input.accountClient.createSiwsNonce({
    walletAddress: input.address,
    chainId: input.chainId,
    intent: input.intent,
  });
  const message = buildSiwsMessage({
    address: input.address,
    chainId: input.chainId,
    nonce: nonceResult.nonce,
    intent: input.intent,
    ...messageConfigFromNonce(nonceResult, input.messageConfig),
  });
  const signature = await input.signMessage(message);
  await input.accountClient.verifySiws({
    message,
    signature,
    walletAddress: input.address,
    chainId: input.chainId,
    intent: input.intent,
    label: input.label,
  });
}

export type AuthMessageConfig = {
  domain: string;
  uri: string;
};

export function resolveAuthMessageConfig(input: {
  baseUrl?: string;
  authDomain?: string;
  authUri?: string;
}): AuthMessageConfig {
  const base = absoluteUrl(input.baseUrl);
  const fallbackOrigin =
    base?.origin ??
    (typeof window !== "undefined" ? window.location.origin : "");
  const fallbackDomain =
    base?.host ?? (typeof window !== "undefined" ? window.location.host : "");
  return {
    domain: normalizeDomain(input.authDomain) ?? fallbackDomain,
    uri: normalizeUri(input.authUri) ?? fallbackOrigin,
  };
}

export function buildSiweMessage(input: {
  address: string;
  chainId: number;
  nonce: string;
  domain: string;
  uri: string;
}): string {
  const { domain, uri } = requireAuthMessageConfig(input);
  return `${domain} wants you to sign in with your Ethereum account:
${input.address}

Sign in to Aomi.

URI: ${uri}
Version: 1
Chain ID: ${input.chainId}
Nonce: ${input.nonce}
Issued At: ${new Date().toISOString()}`;
}

export function buildWalletLinkMessage(input: {
  address: string;
  chainId: number;
  nonce: string;
  domain: string;
  uri: string;
}): string {
  const { domain, uri } = requireAuthMessageConfig(input);
  return `${domain} wants to link this wallet to your Aomi account:
${input.address}

Only sign this message if you want this wallet attached to the current Aomi account.

URI: ${uri}
Version: 1
Chain ID: ${input.chainId}
Nonce: ${input.nonce}
Issued At: ${new Date().toISOString()}`;
}

function messageConfigFromNonce(
  nonce: AomiBackendNonceResponse,
  fallback: AuthMessageConfig,
): AuthMessageConfig {
  return completeAuthMessageConfig({
    domain: normalizeDomain(nonce.domain) ?? normalizeDomain(fallback.domain),
    uri: normalizeUri(nonce.uri) ?? normalizeUri(fallback.uri),
  });
}

function browserAuthMessageConfig(): AuthMessageConfig {
  if (typeof window === "undefined") {
    return { domain: "", uri: "" };
  }
  return {
    domain: window.location.host,
    uri: window.location.origin,
  };
}

function requireAuthMessageConfig(input: AuthMessageConfig): AuthMessageConfig {
  return completeAuthMessageConfig(input);
}

function completeAuthMessageConfig(
  input: Partial<AuthMessageConfig>,
): AuthMessageConfig {
  const browserFallback = browserAuthMessageConfig();
  const uri =
    normalizeUri(input.uri) ??
    normalizeUri(browserFallback.uri) ??
    deriveUriFromDomain(input.domain) ??
    "http://localhost";
  const domain =
    normalizeDomain(input.domain) ??
    normalizeDomain(uri) ??
    normalizeDomain(browserFallback.domain) ??
    "localhost";
  return { domain, uri };
}

function hasAuthMessageConfig(input: Partial<AuthMessageConfig>): boolean {
  const browserFallback = browserAuthMessageConfig();
  const domain =
    normalizeDomain(input.domain) ?? normalizeDomain(browserFallback.domain);
  const uri =
    normalizeUri(input.uri) ??
    normalizeUri(browserFallback.uri) ??
    deriveUriFromDomain(domain);
  return Boolean(domain && uri);
}

function absoluteUrl(value: string | undefined): URL | null {
  if (!value) return null;
  try {
    return new URL(value);
  } catch {
    return null;
  }
}

function normalizeDomain(value: string | undefined): string | undefined {
  const trimmed = value?.trim();
  if (!trimmed) return undefined;
  try {
    const host = new URL(trimmed).host.trim();
    if (host) return host;
  } catch {
    // Fall through to authority parsing below.
  }
  return (
    trimmed
      .replace(/^[a-z][a-z0-9+.-]*:\/\//i, "")
      .replace(/\/.*$/, "")
      .trim() || undefined
  );
}

function normalizeUri(value: string | undefined): string | undefined {
  const trimmed = value?.trim().replace(/\/+$/, "");
  if (!trimmed) return undefined;
  try {
    const url = new URL(trimmed);
    if (url.protocol !== "http:" && url.protocol !== "https:") {
      return undefined;
    }
    return url.toString().replace(/\/+$/, "");
  } catch {
    return undefined;
  }
}

function deriveUriFromDomain(value: string | undefined): string | undefined {
  const domain = normalizeDomain(value);
  if (!domain) return undefined;
  return domain.includes("localhost") || domain.startsWith("127.")
    ? `http://${domain}`
    : `https://${domain}`;
}

import type { AomiWalletKit } from "../types";

/**
 * Canonical sign-out for wallet chrome (WalletPicker, DualWalletBar).
 *
 * The account runtime owns account-vs-widget teardown ordering (it revokes the
 * backend account before the widget session). Here we only ensure the wallet
 * connectors are disconnected afterwards even if that teardown throws, so no
 * provider connection is left dangling. Wallet-kit disconnect alone only signs
 * out the provider and must not substitute for this sequence.
 */
export async function signOutAndDisconnect(
  adapter: AomiWalletKit,
): Promise<void> {
  try {
    await adapter.signOutAccount?.();
  } finally {
    await adapter.disconnect?.({ family: "all" });
  }
}

/** Encode a UTF-8 string to base64 (used for Solana `signMessage` payloads). */
export function utf8ToBase64(value: string): string {
  const bytes = new TextEncoder().encode(value);
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

/**
 * Encode a hex string (with or without a leading `0x`) to base64. Used for
 * Para's `signMessage`, which takes the message digest as a base64 payload.
 */
export function hexToBase64(hex: string): string {
  const normalized = hex.startsWith("0x") ? hex.slice(2) : hex;
  let binary = "";
  for (let index = 0; index < normalized.length; index += 2) {
    binary += String.fromCharCode(
      parseInt(normalized.slice(index, index + 2), 16),
    );
  }
  return btoa(binary);
}

"use client";

import { useEffect, useMemo, useRef } from "react";
import {
  createProviderCredentialAdapter,
  createSiweAccountAuthAdapter,
  createSiwsAccountAuthAdapter,
  createAccountSessionProvider,
  type AccountAuthAdapter,
  type AccountSessionProvider,
} from "@aomi-labs/client";
import type { AuthRuntime, SvmWalletRuntime } from "../composer/types";
import type { EvmWalletRuntime } from "../runtime/evm/wallet-runtime";
import type { WidgetAuthConfig } from "../config/types";
import { utf8ToBase64 } from "./encoding";

export type { WidgetAuthConfig };

/**
 * Single predicate both layers consult to decide whether the widget currently
 * has a usable credential source to mint its own backend session. Keeping the
 * provider-build guard (`useAccountSessionProvider`) and the signed-out gate
 * (`useAomiBackendAccountRuntime`) on the same rule stops them from disagreeing
 * — e.g. an authenticated-but-credential-less provider state that would
 * otherwise fall back to cross-origin cookie mode and 401.
 *
 * - `provider` mode is ready once the host is authenticated AND exposes an
 *   exchangeable credential.
 * - `wallet` mode is ready once a connected external wallet can sign (EVM SIWE
 *   or SVM SIWS); before that it is idle, not an error.
 */
export function widgetCredentialsReady(input: {
  widgetAuth: WidgetAuthConfig;
  authStatus: AuthRuntime["status"];
  hasAuthCredential: boolean;
  evm: EvmWalletRuntime;
  svm?: SvmWalletRuntime;
}): boolean {
  if (input.widgetAuth.mode === "provider") {
    return input.authStatus === "authenticated" && input.hasAuthCredential;
  }
  const connection = input.evm.activeEvmConnection;
  if (connection?.address && connection.chainId && input.evm.signMessageAsync) {
    return true;
  }
  const identity = input.svm?.identity(Date.now());
  return Boolean(identity?.address && input.svm?.execution.signSolanaMessage);
}

/**
 * Build (and dispose) the cross-origin widget session provider for the account
 * runtime. Live auth/EVM/SVM runtimes are mirrored through refs so the memoized
 * provider reads current signers without being rebuilt on every render; it is
 * only rebuilt when a flat identity/config primitive changes.
 */
export function useAccountSessionProvider(input: {
  baseUrl?: string;
  widgetAuth?: WidgetAuthConfig;
  auth: AuthRuntime;
  evm: EvmWalletRuntime;
  svm?: SvmWalletRuntime;
}): AccountSessionProvider | undefined {
  const { baseUrl, widgetAuth, auth, evm, svm } = input;
  const authStatus = auth.status;
  const authSubject = auth.subject;
  const hasAuthCredential = Boolean(auth.getCredential);
  const mode = widgetAuth?.mode;
  const provider =
    widgetAuth?.mode === "provider" ? widgetAuth.provider : undefined;
  const environment =
    widgetAuth?.mode === "provider" ? widgetAuth.environment : undefined;
  const credentialsReady = widgetAuth
    ? widgetCredentialsReady({
        widgetAuth,
        authStatus,
        hasAuthCredential,
        evm,
        svm,
      })
    : false;

  const authRef = useRef(auth);
  const evmRef = useRef(evm);
  const svmRef = useRef(svm);
  authRef.current = auth;
  evmRef.current = evm;
  svmRef.current = svm;

  const accountSessionProvider = useMemo(() => {
    if (!widgetAuth || !baseUrl) return undefined;
    // Do not publish a required bearer source until the configured auth mode
    // can actually mint one. This applies equally to provider and wallet mode:
    // the main Aomi client consumes this provider for threads, REST, and SSE,
    // not only the account runtime, so returning a throwing wallet adapter here
    // would still turn the default signed-out widget boot into an auth error.
    if (!credentialsReady) return undefined;
    let adapter: AccountAuthAdapter;
    if (widgetAuth.mode === "provider") {
      // Provider SDKs briefly report a connected account before their
      // exchangeable credential is ready. Do not expose a required bearer
      // source during that gap: catalog loaders would consume it immediately
      // and turn normal auth boot into "Widget auth identity is unavailable".
      // Same readiness rule the runtime's signed-out gate uses.
      const config = widgetAuth;
      adapter = createProviderCredentialAdapter({
        provider: config.provider,
        environment: config.environment,
        getCredential: async () => authRef.current.getCredential?.() ?? null,
        getSubject: () => authRef.current.subject ?? null,
        signOut: async () => authRef.current.logout?.(),
      });
    } else {
      // SIWE/SIWS wallet mode has no silent refresh: the widget session
      // provider re-runs the adapter's getFingerprint/exchange to renew, which
      // re-prompts the wallet to sign roughly every 29 min (the WST lifetime
      // minus the refresh window). The fingerprint also includes chainId, so
      // switching chains changes the identity and forces a fresh re-sign. Both
      // are currently intended: wallet mode has no offline key to refresh with.
      const currentWalletAdapter = (): AccountAuthAdapter => {
        const evmRuntime = evmRef.current;
        const connection = evmRuntime.activeEvmConnection;
        const evmAddress = connection?.address;
        const evmChainId = connection?.chainId;
        const evmSignMessage = evmRuntime.signMessageAsync;
        if (evmAddress && evmChainId && evmSignMessage) {
          return createSiweAccountAuthAdapter({
            getSigner: async () => ({
              address: evmAddress,
              chainId: evmChainId,
              signMessage: async (message) => evmSignMessage({ message }),
            }),
          });
        }
        const svmRuntime = svmRef.current;
        const identity = svmRuntime?.identity(Date.now());
        const svmAddress = identity?.address;
        const signMessage = svmRuntime?.execution.signSolanaMessage;
        if (svmAddress && signMessage) {
          return createSiwsAccountAuthAdapter({
            getSigner: async () => ({
              address: svmAddress,
              chainId:
                svmRuntime?.selectedNetwork?.cluster ??
                identity?.cluster ??
                "solana:mainnet",
              signMessage: async (message) =>
                (
                  await signMessage({
                    message: utf8ToBase64(message),
                    cluster:
                      svmRuntime?.selectedNetwork?.cluster ?? identity?.cluster,
                  })
                ).signature,
            }),
          });
        }
        throw new Error(
          "Connect an external wallet to authenticate the widget",
        );
      };
      adapter = {
        getFingerprint: () => currentWalletAdapter().getFingerprint(),
        exchange: (options) => currentWalletAdapter().exchange(options),
      };
    }
    return createAccountSessionProvider({ baseUrl, adapter });
    // Refs supply live auth/evm/svm; the provider is only rebuilt when a flat
    // identity/config primitive below changes.
  }, [
    baseUrl,
    authStatus,
    authSubject,
    hasAuthCredential,
    mode,
    environment,
    provider,
    credentialsReady,
  ]);

  useEffect(
    () => () => accountSessionProvider?.dispose(),
    [accountSessionProvider],
  );

  return accountSessionProvider;
}

"use client";

import type { AuthRuntime, SvmWalletRuntime } from "../composer/types";
import type { AccountConfig } from "../config/types";
import type { EvmWalletRuntime } from "../runtime/evm/wallet-runtime";
import { useAomiBackendAccountRuntime } from "./aomi-backend-runtime";
import { DISABLED_ACCOUNT_RUNTIME } from "./disabled-runtime";
import type { AccountRuntime } from "./types";

export function useResolvedAccountRuntime(input: {
  account?: AccountConfig;
  auth: AuthRuntime;
  evm: EvmWalletRuntime;
  svm?: SvmWalletRuntime;
}): AccountRuntime {
  const accountConfig =
    input.account !== false && input.account?.mode === "aomi-backend"
      ? input.account
      : null;
  const runtime = useAomiBackendAccountRuntime({
    enabled: Boolean(accountConfig),
    baseUrl: accountConfig?.baseUrl,
    authDomain: accountConfig?.authDomain,
    authUri: accountConfig?.authUri,
    widgetAuth: accountConfig?.widgetAuth,
    auth: input.auth,
    evm: input.evm,
    svm: input.svm,
  });
  return accountConfig ? runtime : DISABLED_ACCOUNT_RUNTIME;
}

