import type {
  SvmCluster,
  SvmNetworkConfigInput,
  SvmNetworkOption,
} from "../types";

export const DEFAULT_SVM_CLUSTER: SvmCluster = "solana:mainnet";

export const DEFAULT_SVM_RPC_HTTP_URLS: Record<SvmCluster, string> = {
  "solana:mainnet": "https://api.mainnet-beta.solana.com",
  "solana:devnet": "https://api.devnet.solana.com",
  "solana:testnet": "https://api.testnet.solana.com",
};

export function getDefaultSvmNetworkLabel(cluster: SvmCluster): string {
  switch (cluster) {
    case "solana:mainnet":
      return "Solana";
    case "solana:testnet":
      return "Solana Testnet";
    case "solana:devnet":
    default:
      return "Solana Devnet";
  }
}

function buildLegacySvmNetwork(
  config?: SvmNetworkConfigInput,
): SvmNetworkOption {
  const cluster = config?.cluster ?? DEFAULT_SVM_CLUSTER;
  return {
    id: cluster,
    label: getDefaultSvmNetworkLabel(cluster),
    cluster,
    rpcHttpUrl: config?.rpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS[cluster],
    rpcWsUrl: config?.rpcWsUrl,
    isDefault: true,
  };
}

export function normalizeSvmNetworkOptions(
  config?: SvmNetworkConfigInput,
): readonly SvmNetworkOption[] {
  const rawNetworks = config?.networks;
  if (!rawNetworks || rawNetworks.length === 0) {
    return [buildLegacySvmNetwork(config)];
  }

  return rawNetworks.map((network, index) => ({
    id: network.id,
    label: network.label || getDefaultSvmNetworkLabel(network.cluster),
    cluster: network.cluster,
    rpcHttpUrl:
      network.rpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS[network.cluster],
    rpcWsUrl: network.rpcWsUrl,
    isDefault:
      network.isDefault ??
      (index === 0 && !rawNetworks.some((item) => item.isDefault)),
  }));
}

export function resolveSelectedSvmNetwork(
  networks: readonly SvmNetworkOption[],
  selectedNetworkId?: string,
): SvmNetworkOption {
  return (
    networks.find((network) => network.id === selectedNetworkId) ??
    networks.find((network) => network.isDefault) ??
    networks[0]
  );
}

export function buildDefaultSvmNetworkOptions(options?: {
  mainnetRpcHttpUrl?: string;
  mainnetRpcWsUrl?: string;
  devnetRpcHttpUrl?: string;
  devnetRpcWsUrl?: string;
  testnetRpcHttpUrl?: string;
  testnetRpcWsUrl?: string;
}): readonly SvmNetworkOption[] {
  return [
    {
      id: "solana-mainnet",
      label: "Solana",
      cluster: "solana:mainnet",
      rpcHttpUrl:
        options?.mainnetRpcHttpUrl ??
        DEFAULT_SVM_RPC_HTTP_URLS["solana:mainnet"],
      rpcWsUrl: options?.mainnetRpcWsUrl,
      isDefault: true,
    },
    {
      id: "solana-devnet",
      label: "Solana Devnet",
      cluster: "solana:devnet",
      rpcHttpUrl:
        options?.devnetRpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS["solana:devnet"],
      rpcWsUrl: options?.devnetRpcWsUrl,
    },
    {
      id: "solana-testnet",
      label: "Solana Testnet",
      cluster: "solana:testnet",
      rpcHttpUrl:
        options?.testnetRpcHttpUrl ??
        DEFAULT_SVM_RPC_HTTP_URLS["solana:testnet"],
      rpcWsUrl: options?.testnetRpcWsUrl,
    },
  ];
}

"use client";

import {
  Connection as SolanaConnection,
  Transaction as SolanaTransaction,
  VersionedTransaction,
} from "@solana/web3.js";
import type {
  WalletSolanaSignMessagePayload,
  WalletSolanaSignPayload,
} from "@aomi-labs/react";
import type { SafeSvmWalletState } from "./wallet-runtime";

function decodeBase64(value: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return new Uint8Array(Buffer.from(value, "base64"));
  }
  const bin = atob(value);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function encodeBase64(bytes: Uint8Array): string {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(bytes).toString("base64");
  }
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

function deserializeSolanaTransaction(
  bytes: Uint8Array,
): VersionedTransaction | SolanaTransaction {
  try {
    return VersionedTransaction.deserialize(bytes);
  } catch {
    return SolanaTransaction.from(bytes);
  }
}

export function buildSvmTransactionMethods(
  wallet: SafeSvmWalletState,
  config: {
    rpcHttpUrl: string;
    rpcWsUrl?: string;
    preferDirectSend: boolean;
  },
): {
  signSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signedTx: string }>;
  signSolanaMessage?: (
    payload: WalletSolanaSignMessagePayload,
  ) => Promise<{ signature: string }>;
  sendSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signature: string; signedTx?: string }>;
  signAndSendSolanaTransaction?: (
    payload: WalletSolanaSignPayload,
  ) => Promise<{ signature: string; signedTx?: string }>;
  solanaRpcHttpUrl: string;
  solanaRpcWsUrl?: string;
} {
  const signTransaction = wallet.signTransaction;
  const signMessage = wallet.signMessage;
  const sendTransaction = wallet.sendTransaction;

  return {
    signSolanaTransaction: signTransaction
      ? async (payload: WalletSolanaSignPayload) => {
          if (!payload.unsignedTx) {
            throw new Error("Missing unsigned_tx payload");
          }
          const tx = deserializeSolanaTransaction(
            decodeBase64(payload.unsignedTx),
          );
          const signed = await signTransaction(tx);
          return { signedTx: encodeBase64(signed.serialize()) };
        }
      : undefined,
    signSolanaMessage: signMessage
      ? async (payload: WalletSolanaSignMessagePayload) => {
          if (!payload.message) {
            throw new Error("Missing message payload");
          }
          const signature = await signMessage(decodeBase64(payload.message));
          return { signature: encodeBase64(signature) };
        }
      : undefined,
    sendSolanaTransaction: sendTransaction
      ? async (payload: WalletSolanaSignPayload) => {
          if (!payload.unsignedTx) {
            throw new Error("Missing unsigned_tx payload");
          }
          const connection = new SolanaConnection(
            config.rpcHttpUrl,
            "confirmed",
          );
          const tx = deserializeSolanaTransaction(
            decodeBase64(payload.unsignedTx),
          );
          const signature = await sendTransaction(tx, connection);
          return { signature };
        }
      : undefined,
    signAndSendSolanaTransaction:
      sendTransaction && config.preferDirectSend
        ? async (payload: WalletSolanaSignPayload) => {
            if (!payload.unsignedTx) {
              throw new Error("Missing unsigned_tx payload");
            }
            const connection = new SolanaConnection(
              config.rpcHttpUrl,
              "confirmed",
            );
            const tx = deserializeSolanaTransaction(
              decodeBase64(payload.unsignedTx),
            );
            const signature = await sendTransaction(tx, connection);
            return { signature };
          }
        : undefined,
    solanaRpcHttpUrl: config.rpcHttpUrl,
    solanaRpcWsUrl: config.rpcWsUrl,
  };
}

