import { useEffect, useMemo, useRef } from "react";
import type { WalletRegistryStore } from "../../registry/store";
import type { SafeSvmWalletState } from "./wallet-runtime";

export function useSvmRegistrySource(
  store: WalletRegistryStore,
  opts: { svmWallet: SafeSvmWalletState },
): void {
  const snapshotKey = useMemo(
    () =>
      `${opts.svmWallet.publicKey ?? ""}:${opts.svmWallet.walletName ?? ""}`,
    [opts.svmWallet.publicKey, opts.svmWallet.walletName],
  );
  const previousKeyRef = useRef<string | null>(null);

  useEffect(() => {
    if (previousKeyRef.current === snapshotKey) return;
    previousKeyRef.current = snapshotKey;
    store.dispatch({
      type: "svm/changed",
      publicKey: opts.svmWallet.publicKey ?? null,
      kind: opts.svmWallet.transport === "embedded" ? "embedded-session" : "svm",
      providerId: opts.svmWallet.providerId,
      walletName: opts.svmWallet.walletName ?? null,
      now: Date.now(),
    });
  }, [opts.svmWallet.publicKey, opts.svmWallet.walletName, snapshotKey, store]);

}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useWallet as useSolanaWallet } from "@solana/wallet-adapter-react";
import {
  Connection as SolanaConnection,
  Transaction as SolanaTransaction,
  VersionedTransaction,
} from "@solana/web3.js";
import type {
  AomiWalletOption,
  SvmNetworkOption,
  SvmWalletDescriptor,
} from "../../types";
import { SVM_WALLET_ALLOWLIST } from "../../catalog/svm-wallet-catalog";
import { canonicalWalletKey } from "../../catalog/wallet-branding";
import { selectAccounts, selectSvmIdentity } from "../../registry/selectors";
import type { WalletRegistryStore } from "../../registry/store";
import type { SvmWalletRuntime } from "../../composer/types";
import {
  DEFAULT_SVM_CLUSTER,
  DEFAULT_SVM_RPC_HTTP_URLS,
} from "../../catalog/svm-networks";
import { useSvmRegistrySource } from "./registry-source";
import { buildSvmTransactionMethods } from "./transactions";

export type SafeSvmWalletState = {
  publicKey: string | undefined;
  connected: boolean;
  connecting: boolean;
  disconnecting: boolean;
  walletName: string | undefined;
  providerId?: string;
  transport?: "extension" | "embedded" | "mwa";
  wallets: Array<{
    adapter: {
      name: string;
      readyState: SvmWalletReadyState;
    };
    readyState: SvmWalletReadyState;
  }>;
  select: ((walletName: SvmWalletName) => void) | undefined;
  connect: (() => Promise<void>) | undefined;
  disconnect: (() => Promise<void>) | undefined;
  signTransaction:
    | ((
        tx: VersionedTransaction | SolanaTransaction,
      ) => Promise<VersionedTransaction | SolanaTransaction>)
    | undefined;
  signAllTransactions:
    | ((
        txs: Array<VersionedTransaction | SolanaTransaction>,
      ) => Promise<Array<VersionedTransaction | SolanaTransaction>>)
    | undefined;
  signMessage: ((message: Uint8Array) => Promise<Uint8Array>) | undefined;
  sendTransaction:
    | ((
        tx: VersionedTransaction | SolanaTransaction,
        connection: SolanaConnection,
      ) => Promise<string>)
    | undefined;
};

const DISCONNECTED_SVM_WALLET: SafeSvmWalletState = {
  publicKey: undefined,
  connected: false,
  connecting: false,
  disconnecting: false,
  walletName: undefined,
  wallets: [],
  select: undefined,
  connect: undefined,
  disconnect: undefined,
  signTransaction: undefined,
  signAllTransactions: undefined,
  signMessage: undefined,
  sendTransaction: undefined,
};

export const DEFAULT_SVM_ENDPOINT =
  DEFAULT_SVM_RPC_HTTP_URLS[DEFAULT_SVM_CLUSTER];
const SVM_AUTOCONNECT_GRACE_MS = 400;

type SvmWalletSource = "external" | "embedded";

type SvmWalletReadyState =
  | "Installed"
  | "NotDetected"
  | "Loadable"
  | "Unsupported";
type SvmWalletName = Parameters<
  ReturnType<typeof useSolanaWallet>["select"]
>[0];

/**
 * Outside a `WalletProvider`, `useWallet()` does not throw — it returns the
 * adapter library's DEFAULT_CONTEXT, whose `publicKey`/`wallet`/`wallets` are
 * accessor properties that `console.error` a missing-provider message on every
 * read. A provider-supplied context value is a plain object with data
 * properties, so an accessor on `publicKey` identifies the default context
 * without invoking the getter (descriptor lookups do not run getters).
 */
function isMissingSvmProviderContext(
  wallet: ReturnType<typeof useSolanaWallet>,
): boolean {
  return Boolean(Object.getOwnPropertyDescriptor(wallet, "publicKey")?.get);
}

export function useSafeSvmWallet(): SafeSvmWalletState {
  const context = useSolanaWallet();
  if (isMissingSvmProviderContext(context)) {
    return DISCONNECTED_SVM_WALLET;
  }
  try {
    const wallet = context;
    return {
      publicKey: wallet.publicKey?.toBase58(),
      connected: wallet.connected,
      connecting: wallet.connecting,
      disconnecting: wallet.disconnecting,
      walletName: wallet.wallet?.adapter?.name,
      wallets: wallet.wallets,
      select: wallet.select,
      connect: wallet.connect,
      disconnect: wallet.disconnect,
      signTransaction: wallet.signTransaction,
      signAllTransactions: wallet.signAllTransactions,
      signMessage: wallet.signMessage,
      sendTransaction: wallet.sendTransaction,
    };
  } catch {
    return DISCONNECTED_SVM_WALLET;
  }
}

function hasSelectedSvmWallet(wallet: SafeSvmWalletState): boolean {
  return Boolean(
    wallet.publicKey ||
    wallet.connected ||
    wallet.connecting ||
    wallet.walletName,
  );
}

/**
 * Keep the standard Solana wallet-adapter source available when an auth
 * provider also contributes embedded Solana wallets. Provider plugins augment
 * the generic source; they never replace it.
 */
export function useMergedSvmWallet(
  external: SafeSvmWalletState,
  embedded: SafeSvmWalletState,
): SafeSvmWalletState {
  const preferredSource = hasSelectedSvmWallet(external)
    ? "external"
    : hasSelectedSvmWallet(embedded)
      ? "embedded"
      : "external";
  const [selectedSource, setSelectedSource] =
    useState<SvmWalletSource>(preferredSource);
  const sourceSelectedByUser = useRef(false);

  useEffect(() => {
    if (sourceSelectedByUser.current) return;
    setSelectedSource(preferredSource);
  }, [preferredSource]);

  const active = selectedSource === "external" ? external : embedded;
  const externalNames = useMemo(
    () => new Set(external.wallets.map((entry) => entry.adapter.name)),
    [external.wallets],
  );
  const embeddedNames = useMemo(
    () => new Set(embedded.wallets.map((entry) => entry.adapter.name)),
    [embedded.wallets],
  );
  const wallets = useMemo(() => {
    const seen = new Set<string>();
    return [...external.wallets, ...embedded.wallets].filter((entry) => {
      const name = String(entry.adapter.name);
      if (seen.has(name)) return false;
      seen.add(name);
      return true;
    });
  }, [embedded.wallets, external.wallets]);
  const select = useCallback(
    (walletName: SvmWalletName) => {
      const name = String(walletName);
      if (externalNames.has(name)) {
        sourceSelectedByUser.current = true;
        setSelectedSource("external");
        external.select?.(walletName);
        return;
      }
      if (embeddedNames.has(name)) {
        sourceSelectedByUser.current = true;
        setSelectedSource("embedded");
        embedded.select?.(walletName);
      }
    },
    [embedded, embeddedNames, external, externalNames],
  );

  return useMemo(
    () => ({
      ...active,
      wallets,
      select,
    }),
    [active, select, wallets],
  );
}

export function detectSvmTransport(
  walletName: string | undefined,
): "extension" | "embedded" | "mwa" {
  const normalized = walletName?.toLowerCase() ?? "";
  if (
    normalized.includes("mobile wallet adapter") ||
    normalized.includes("solana mobile") ||
    normalized.includes("mwa")
  ) {
    return "mwa";
  }
  return "extension";
}

function isUsableWalletReadyState(readyState: SvmWalletReadyState): boolean {
  return readyState === "Installed" || readyState === "Loadable";
}

function walletPriority(name: string): number {
  const normalized = name.toLowerCase();
  if (normalized.includes("phantom")) return 0;
  if (normalized.includes("solflare")) return 1;
  if (normalized.includes("backpack")) return 2;
  if (normalized.includes("glow")) return 3;
  return 10;
}

function pickPreferredSvmWallet(wallet: SafeSvmWalletState) {
  return [...wallet.wallets]
    .filter((candidate) => isUsableWalletReadyState(candidate.readyState))
    .sort((left, right) => {
      const installedDelta =
        Number(left.readyState === "Installed") -
        Number(right.readyState === "Installed");
      if (installedDelta !== 0) {
        return -installedDelta;
      }
      return (
        walletPriority(left.adapter.name) - walletPriority(right.adapter.name)
      );
    })[0];
}

export type SvmConnectAttempt =
  | { status: "connected" }
  | { status: "unavailable" }
  | {
      status: "selecting";
      walletName: string;
    };

export async function connectPreferredSvmWallet(
  wallet: SafeSvmWalletState,
): Promise<SvmConnectAttempt> {
  if (wallet.publicKey || wallet.connected) {
    return { status: "connected" };
  }

  if (!wallet.select || !wallet.connect) {
    return { status: "unavailable" };
  }

  if (wallet.walletName) {
    await wallet.connect();
    return { status: "connected" };
  }

  const selectedWallet = pickPreferredSvmWallet(wallet);
  if (!selectedWallet) {
    return { status: "unavailable" };
  }

  wallet.select(selectedWallet.adapter.name as SvmWalletName);
  return { status: "selecting", walletName: selectedWallet.adapter.name };
}

export async function executeSvmWalletConnect({
  getCurrent,
  walletName,
  waitForAutoConnect = () =>
    new Promise<void>((resolve) =>
      setTimeout(resolve, SVM_AUTOCONNECT_GRACE_MS),
    ),
}: {
  getCurrent: () => SafeSvmWalletState;
  walletName: string;
  waitForAutoConnect?: () => Promise<void>;
}): Promise<void> {
  const current = getCurrent();
  if (current.publicKey && current.walletName === walletName) return;
  if (current.walletName !== walletName) {
    current.select?.(walletName as SvmWalletName);
  }
  if (!current.connect) return;

  // WalletProvider's autoConnect reacts to select(). Give it the first chance
  // to connect, then invoke connect() only when no automatic attempt started.
  // Calling both concurrently makes Phantom reject with WalletConnectionError.
  await waitForAutoConnect();
  const selected = getCurrent();
  if (selected.publicKey || selected.connected || selected.connecting) return;
  // A newer picker action owns a different adapter now. Let that request
  // connect it instead of allowing this stale grace timer to race it.
  if (selected.walletName && selected.walletName !== walletName) return;
  await selected.connect?.();
}

export function getSvmCapabilitySnapshot(
  wallet: SafeSvmWalletState | undefined,
) {
  if (!wallet?.publicKey) {
    return undefined;
  }
  return {
    canSignMessage: Boolean(wallet.signMessage),
    canSignTransaction: Boolean(wallet.signTransaction),
    canSignAllTransactions: Boolean(wallet.signAllTransactions),
    canSendTransaction: Boolean(wallet.sendTransaction),
    canSignAndSendTransaction: Boolean(wallet.sendTransaction),
  };
}

function buildSvmWalletDescriptors(
  wallet: SafeSvmWalletState,
): SvmWalletDescriptor[] {
  return wallet.wallets
    .filter((entry) =>
      SVM_WALLET_ALLOWLIST.has(canonicalWalletKey(entry.adapter.name)),
    )
    .map((entry) => ({
      name: entry.adapter.name,
      installed: entry.readyState === "Installed",
      ready:
        entry.readyState === "Installed" || entry.readyState === "Loadable",
    }));
}

function toSvmWalletOption(descriptor: SvmWalletDescriptor): AomiWalletOption {
  return {
    id: descriptor.name,
    label: descriptor.name,
    family: "svm",
    kind: "solana",
    status: descriptor.ready
      ? descriptor.installed
        ? "installed"
        : "available"
      : "unavailable",
    installed: descriptor.installed,
    ready: descriptor.ready,
  };
}

function useLatestRef<T>(value: T) {
  const ref = useRef(value);
  useEffect(() => {
    ref.current = value;
  }, [value]);
  return ref;
}

export function useSvmWalletRuntime({
  preferDirectSend = true,
  registryStore,
  selectedNetwork,
  supportedNetworks,
  setSelectedNetworkId,
  wallet: walletOverride,
}: {
  preferDirectSend?: boolean;
  registryStore: WalletRegistryStore;
  selectedNetwork?: SvmNetworkOption;
  supportedNetworks: readonly SvmNetworkOption[];
  setSelectedNetworkId: (id: string) => void;
  wallet?: SafeSvmWalletState;
}): SvmWalletRuntime {
  const wallet = walletOverride ?? DISCONNECTED_SVM_WALLET;
  const walletRef = useLatestRef(wallet);

  useSvmRegistrySource(registryStore, { svmWallet: wallet });

  const settleConnect = useCallback(
    (walletName: string) => {
      registryStore.dispatch({
        type: "svm/connect-settled",
        walletName,
        now: Date.now(),
      });
    },
    [registryStore],
  );

  const executeConnect = useCallback(
    async (walletName: string) => {
      try {
        await executeSvmWalletConnect({
          getCurrent: () => walletRef.current,
          walletName,
        });
      } finally {
        settleConnect(walletName);
      }
    },
    [settleConnect, walletRef],
  );

  const executeDisconnect = useCallback(async () => {
    const current = walletRef.current;
    if (!current.publicKey || !current.disconnect) return;
    await current.disconnect();
  }, [walletRef]);

  useEffect(() => {
    registryStore.updateExecutors({
      svmConnect: executeConnect,
      svmDisconnect: executeDisconnect,
    });
  }, [executeConnect, executeDisconnect, registryStore]);

  const connect = useCallback(
    async (optionId?: string) => {
      if (
        (wallet.publicKey || wallet.connected) &&
        (!optionId || optionId === wallet.walletName)
      ) {
        return;
      }
      const walletName =
        optionId ?? pickPreferredSvmWallet(wallet)?.adapter.name;
      if (!walletName) return;
      registryStore.dispatch({
        type: "svm/connect-requested",
        walletName,
        now: Date.now(),
      });
    },
    [registryStore, wallet],
  );

  const disconnect = useCallback(async () => {
    registryStore.dispatch({
      type: "user/disconnect-family",
      family: "svm",
      now: Date.now(),
    });
  }, [registryStore]);

  const selectAccount = useCallback(
    async (accountId: string) => {
      const account = selectAccounts(
        registryStore.getSnapshot(),
        "svm",
        Date.now(),
      ).find((candidate) => candidate.id === accountId);
      if (!account) return;
      registryStore.dispatch({
        type: "user/select-active",
        family: "svm",
        address: account.address,
        uid: account.id,
        stableId: account.id,
        now: Date.now(),
      });
    },
    [registryStore],
  );

  const selectNetwork = useCallback(
    async (networkId: string | number) => {
      const id = String(networkId);
      if (selectedNetwork?.id === id) return;
      if (wallet.publicKey && wallet.disconnect) {
        await wallet.disconnect();
      }
      setSelectedNetworkId(id);
    },
    [selectedNetwork?.id, setSelectedNetworkId, wallet],
  );

  const config = useMemo(
    () => ({
      rpcHttpUrl:
        selectedNetwork?.rpcHttpUrl ??
        DEFAULT_SVM_RPC_HTTP_URLS[
          selectedNetwork?.cluster ?? DEFAULT_SVM_CLUSTER
        ],
      rpcWsUrl: selectedNetwork?.rpcWsUrl,
      preferDirectSend,
    }),
    [preferDirectSend, selectedNetwork],
  );
  const execution = useMemo(
    () => buildSvmTransactionMethods(wallet, config),
    [config, wallet],
  );
  const options = useMemo(
    () => buildSvmWalletDescriptors(wallet).map(toSvmWalletOption),
    [wallet],
  );
  const accounts = useCallback(
    (now: number) => selectAccounts(registryStore.getSnapshot(), "svm", now),
    [registryStore],
  );
  const identity = useCallback(
    (now: number) => {
      const registryIdentity = selectSvmIdentity(
        registryStore.getSnapshot(),
        now,
      );
      return {
        ...registryIdentity,
        cluster: selectedNetwork?.cluster ?? DEFAULT_SVM_CLUSTER,
        walletSource: registryIdentity.address
          ? wallet.transport === "embedded"
            ? ("embedded" as const)
            : ("injected" as const)
          : undefined,
        transport: registryIdentity.address
          ? (wallet.transport ??
            detectSvmTransport(registryIdentity.walletName))
          : undefined,
        capabilities: getSvmCapabilitySnapshot(wallet),
      };
    },
    [registryStore, selectedNetwork?.cluster, wallet],
  );

  return {
    status:
      wallet.select || wallet.connect || wallet.publicKey
        ? "ready"
        : "unavailable",
    registryStore,
    identity,
    accounts,
    activeAccount: accounts(Date.now()).find((account) => account.active),
    options,
    supportedNetworks,
    selectedNetwork,
    connect,
    disconnect,
    selectAccount,
    selectNetwork,
    execution,
  };
}

import type { WalletFamily, WalletSource } from "../types";

/** Runtime id vs stable id: wagmi connector `uid` is regenerated every page load;
 * `connector.id` (e.g. hosted SDK ids, "io.metamask", "metaMaskSDK", "walletConnect") is stable
 * across loads. Persist stable ids + addresses; resolve uids at runtime.
 */
export type RegistryConnection = {
  key: string;
  family: WalletFamily;
  uid: string;
  stableId: string;
  kind: "embedded-session" | "external-evm" | "walletconnect" | "svm";
  address: string;
  addresses: string[];
  chainId?: number;
  walletName?: string;
  providerId?: string;
};

export type RegistryConnectionOrderItem = {
  family: WalletFamily;
  stableId: string;
  address: string;
};

export type ActiveRef = {
  family: WalletFamily;
  address: string;
  uid?: string;
  stableId?: string;
};

export type RegistryPhase = "booting" | "settling" | "stable" | "rebuilding";

export type EvmGraceState = {
  last: {
    address: string;
    chainId?: number;
    connectorId?: string;
    walletName?: string;
    walletSource?: WalletSource;
  } | null;
  disconnectedAt: number | null;
};

export type EmbeddedSessionState = {
  up: boolean;
  providerId: string | null;
  uid: string | null;
  stableId: string | null;
  walletName: string | null;
  embeddedEvmAddress: string | null;
  chainId: number | null;
};

export type AuthFlowSuppressionReason =
  | "provider-social-login"
  | "provider-auth-modal"
  | "provider-evm-connect-fallback"
  | "provider-account-modal"
  | (string & {});

export type WalletRegistryState = {
  phase: RegistryPhase;
  connections: RegistryConnection[];
  connectionOrder: RegistryConnectionOrderItem[];
  activeByFamily: Partial<Record<WalletFamily, ActiveRef>>;
  intents: {
    droppedAddresses: string[];
    providerSessionDetached: boolean;
    explicitFamilyDisconnect: Partial<Record<WalletFamily, boolean>>;
    pendingSvmWallet: string | null;
    preferEmbeddedOnConnect: boolean;
  };
  heal: {
    expected: Array<{ stableId: string; address: string }>;
    reattachBudget: number;
    suppressedUntil: number | null;
    suppressionReason: AuthFlowSuppressionReason | null;
  };
  evmGrace: EvmGraceState;
  embeddedSession: EmbeddedSessionState;
};

export type RegistryEvent =
  | { type: "boot/init"; persisted: PersistedRegistryV1 | null; now: number }
  | {
      type: "wagmi/connections-changed";
      connections: Array<Omit<RegistryConnection, "key" | "kind">>;
      now: number;
    }
  | { type: "wagmi/config-rebuilt"; now: number }
  | { type: "wagmi/brands-changed"; brands: Record<string, string> }
  | { type: "wagmi/settled"; now: number }
  | {
      type: "provider/embedded-session-changed";
      up: boolean;
      providerId: string;
      uid: string;
      stableId: string;
      walletName: string;
      embeddedEvmAddress: string | null;
      chainId?: number | null;
      now: number;
    }
  | {
      type: "provider/auth-flow-started";
      reason: AuthFlowSuppressionReason;
      now: number;
    }
  | {
      type: "svm/changed";
      publicKey: string | null;
      uid?: string;
      stableId?: string;
      kind?: Extract<RegistryConnection["kind"], "embedded-session" | "svm">;
      providerId?: string;
      walletName: string | null;
      now: number;
    }
  | { type: "svm/connect-requested"; walletName: string; now: number }
  | { type: "svm/connect-settled"; walletName: string; now: number }
  | {
      type: "user/select-active";
      family: WalletFamily;
      address: string;
      uid: string;
      stableId: string;
      now: number;
    }
  | {
      type: "user/connect-succeeded";
      family: WalletFamily;
      address: string;
      uid: string;
      stableId: string;
      now: number;
    }
  | { type: "user/provider-reconnect-requested"; now: number }
  | {
      type: "user/disconnect-account";
      address: string;
      uids: string[];
      isProviderOwnedAccount: boolean;
      othersRemain: boolean;
      markDroppedAddress?: boolean;
      now: number;
    }
  | {
      type: "user/disconnect-family";
      family: WalletFamily | "all";
      now: number;
    };

export type RegistryCommand =
  | { kind: "wagmi/reconnect"; stableIds: string[] }
  | { kind: "wagmi/connect"; stableId: string }
  | { kind: "wagmi/disconnect"; uid: string }
  | { kind: "svm/connect"; walletName: string }
  | { kind: "svm/disconnect" }
  | { kind: "provider/logout" }
  | { kind: "persist" }
  | { kind: "debug"; event: string; data?: Record<string, unknown> };

export type PersistedRegistryV1 = {
  version: 1;
  active: Partial<Record<WalletFamily, { address: string; stableId?: string }>>;
  order?: RegistryConnectionOrderItem[];
  droppedAddresses: string[];
  providerSessionDetached: boolean;
};

/** Public address projection from the canonical `GET /api/account` response. */
export type WalletLink = {
  address: string;
  family: WalletFamily;
  linkedVia: "para" | "privy" | "challenge" | (string & {});
  subject: string;
  verifiedAt: number;
};

export const REGISTRY_STORAGE_KEY = "aomi.wallet.registry.v1";
export const POPUP_REATTACH_BUDGET = 2;
export const REATTACH_SUPPRESSION_MS = 300_000;
export const SETTLE_QUIET_MS = 1_200;
export const AUTH_FLOW_RECONNECT_SETTLE_MS = 8_000;
export const EVM_IDENTITY_GRACE_MS = 1_800;

import { resolveActive, countPlannedHealConnects } from "./policy";
import type {
  ActiveRef,
  EmbeddedSessionState,
  PersistedRegistryV1,
  RegistryConnection,
  RegistryConnectionOrderItem,
  RegistryEvent,
  WalletRegistryState,
} from "./types";
import { POPUP_REATTACH_BUDGET, REATTACH_SUPPRESSION_MS } from "./types";

export function createInitialState(): WalletRegistryState {
  return {
    phase: "booting",
    connections: [],
    connectionOrder: [],
    activeByFamily: {},
    intents: {
      droppedAddresses: [],
      providerSessionDetached: false,
      explicitFamilyDisconnect: {},
      pendingSvmWallet: null,
      preferEmbeddedOnConnect: false,
    },
    heal: {
      expected: [],
      reattachBudget: POPUP_REATTACH_BUDGET,
      suppressedUntil: null,
      suppressionReason: null,
    },
    evmGrace: {
      last: null,
      disconnectedAt: null,
    },
    embeddedSession: {
      up: false,
      providerId: null,
      uid: null,
      stableId: null,
      walletName: null,
      embeddedEvmAddress: null,
      chainId: null,
    },
  };
}

function normalizeAddress(
  family: RegistryConnectionOrderItem["family"],
  address: string,
): string {
  return family === "evm" ? address.toLowerCase() : address;
}

function connectionOrderItem(
  connection: RegistryConnection,
): RegistryConnectionOrderItem {
  return {
    family: connection.family,
    stableId: connection.stableId,
    address: normalizeAddress(connection.family, connection.address),
  };
}

function connectionOrderKey(item: RegistryConnectionOrderItem): string {
  return `${item.family}:${item.stableId}:${normalizeAddress(
    item.family,
    item.address,
  )}`;
}

function reconcileConnectionOrder(
  previous: readonly RegistryConnectionOrderItem[],
  connections: readonly RegistryConnection[],
): RegistryConnectionOrderItem[] {
  const liveKeys = new Set(connections.map((connection) =>
    connectionOrderKey(connectionOrderItem(connection)),
  ));
  const next: RegistryConnectionOrderItem[] = [];
  const seen = new Set<string>();

  for (const item of previous) {
    const key = connectionOrderKey(item);
    if (!liveKeys.has(key) || seen.has(key)) continue;
    next.push({
      ...item,
      address: normalizeAddress(item.family, item.address),
    });
    seen.add(key);
  }

  for (const connection of connections) {
    const item = connectionOrderItem(connection);
    const key = connectionOrderKey(item);
    if (seen.has(key)) continue;
    next.push(item);
    seen.add(key);
  }

  return next;
}

function applyConnectionOrder(
  connections: readonly RegistryConnection[],
  order: readonly RegistryConnectionOrderItem[],
): RegistryConnection[] {
  if (connections.length < 2) return [...connections];
  const byKey = new Map<string, RegistryConnection[]>();
  for (const connection of connections) {
    const key = connectionOrderKey(connectionOrderItem(connection));
    const bucket = byKey.get(key);
    if (bucket) bucket.push(connection);
    else byKey.set(key, [connection]);
  }

  const ordered: RegistryConnection[] = [];
  for (const item of order) {
    const key = connectionOrderKey(item);
    const bucket = byKey.get(key);
    if (!bucket?.length) continue;
    ordered.push(...bucket);
    byKey.delete(key);
  }
  for (const connection of connections) {
    const key = connectionOrderKey(connectionOrderItem(connection));
    const bucket = byKey.get(key);
    if (!bucket?.length) continue;
    ordered.push(...bucket);
    byKey.delete(key);
  }
  return ordered;
}

function withConnectionOrder(state: WalletRegistryState): WalletRegistryState {
  const baseOrder =
    state.connectionOrder.length > 0
      ? state.connectionOrder
      : state.connections.map(connectionOrderItem);
  const connectionOrder = reconcileConnectionOrder(baseOrder, state.connections);
  return {
    ...state,
    connectionOrder,
    connections: applyConnectionOrder(state.connections, connectionOrder),
  };
}

function activeFromPersisted(
  persisted: PersistedRegistryV1 | null,
): WalletRegistryState["activeByFamily"] {
  if (!persisted) return {};
  const active: WalletRegistryState["activeByFamily"] = {};
  if (persisted.active.evm?.address) {
    active.evm = {
      family: "evm",
      address: persisted.active.evm.address.toLowerCase(),
      stableId: persisted.active.evm.stableId,
    };
  }
  const persistedSvm =
    persisted.active.svm ??
    (persisted.active as typeof persisted.active & {
      solana?: { address: string; stableId?: string };
    }).solana;
  if (persistedSvm?.address) {
    active.svm = {
      family: "svm",
      address: persistedSvm.address,
      stableId: persistedSvm.stableId,
    };
  }
  return active;
}

function classifyConnection(
  connection: Omit<RegistryConnection, "key" | "kind">,
  embeddedSession: EmbeddedSessionState,
): RegistryConnection {
  const stableId = connection.stableId;
  const kind =
    connection.family === "svm"
      ? "svm"
      : stableId === embeddedSession.stableId
        ? "embedded-session"
        : stableId === "walletConnect"
          ? "walletconnect"
          : "external-evm";
  const address =
    connection.family === "evm"
      ? connection.address.toLowerCase()
      : connection.address;

  return {
    ...connection,
    key: `${connection.family}:${connection.uid}`,
    kind,
    address,
    addresses:
      connection.family === "evm"
        ? connection.addresses.map((item) => item.toLowerCase())
        : connection.addresses,
  };
}

function withResolvedActive(
  state: WalletRegistryState,
  families: ReadonlyArray<"evm" | "svm"> = ["evm", "svm"],
): WalletRegistryState {
  const activeByFamily = { ...state.activeByFamily };
  for (const family of families) {
    const active = resolveActive(state, family);
    if (active) activeByFamily[family] = active;
    else delete activeByFamily[family];
  }
  return { ...state, activeByFamily };
}

function currentActiveEvmConnection(
  state: WalletRegistryState,
): RegistryConnection | undefined {
  const active = state.activeByFamily.evm;
  if (!active) return undefined;
  return state.connections.find((connection) => {
    if (connection.family !== "evm") return false;
    if (active.uid && connection.uid === active.uid) return true;
    if (active.stableId && connection.stableId !== active.stableId) {
      return false;
    }
    return connection.address.toLowerCase() === active.address.toLowerCase();
  });
}

function isSyntheticEmbeddedSessionConnection(
  state: WalletRegistryState,
  connection: RegistryConnection,
): boolean {
  return (
    connection.kind === "embedded-session" &&
    Boolean(state.embeddedSession.uid) &&
    connection.uid === state.embeddedSession.uid
  );
}

function withoutSyntheticEmbeddedSessionConnection(
  state: WalletRegistryState,
  connections: readonly RegistryConnection[],
): RegistryConnection[] {
  return connections.filter(
    (connection) => !isSyntheticEmbeddedSessionConnection(state, connection),
  );
}

function hasEmbeddedSessionIdentity(
  session: EmbeddedSessionState,
): session is EmbeddedSessionState & {
  uid: string;
  stableId: string;
  walletName: string;
  embeddedEvmAddress: string;
} {
  return Boolean(
    session.up &&
    session.uid &&
    session.stableId &&
    session.walletName &&
    session.embeddedEvmAddress,
  );
}

function withEmbeddedSessionConnection(
  state: WalletRegistryState,
): WalletRegistryState {
  const connections = withoutSyntheticEmbeddedSessionConnection(
    state,
    state.connections,
  );
  const session = state.embeddedSession;
  if (
    !hasEmbeddedSessionIdentity(session) ||
    state.intents.providerSessionDetached
  ) {
    return withConnectionOrder({ ...state, connections });
  }
  const address = session.embeddedEvmAddress.toLowerCase();
  const hasLiveEmbeddedConnection = connections.some(
    (connection) =>
      connection.family === "evm" &&
      connection.stableId === session.stableId &&
      connection.address.toLowerCase() === address.toLowerCase(),
  );
  if (hasLiveEmbeddedConnection) {
    return withConnectionOrder({ ...state, connections });
  }
  return withConnectionOrder({
    ...state,
    connections: [
      ...connections,
      {
        key: `evm:${session.uid}`,
        family: "evm",
        uid: session.uid,
        stableId: session.stableId,
        kind: "embedded-session",
        address,
        addresses: [address],
        chainId: session.chainId ?? undefined,
        walletName: session.walletName,
        providerId: session.providerId ?? undefined,
      },
    ],
  });
}

function withPreferredEmbeddedSessionActive(
  state: WalletRegistryState,
): WalletRegistryState {
  if (!state.intents.preferEmbeddedOnConnect) return state;
  const embedded = state.connections.find(
    (connection) =>
      connection.family === "evm" && connection.kind === "embedded-session",
  );
  if (!embedded) return state;
  return {
    ...state,
    activeByFamily: {
      ...state.activeByFamily,
      evm: {
        family: "evm",
        address: embedded.address,
        uid: embedded.uid,
        stableId: embedded.stableId,
      },
    },
    intents: {
      ...state.intents,
      preferEmbeddedOnConnect: false,
    },
  };
}

function withEvmGrace(
  previous: WalletRegistryState,
  next: WalletRegistryState,
  now: number,
): WalletRegistryState {
  const current = currentActiveEvmConnection(next);
  if (current) {
    return {
      ...next,
      evmGrace: {
        last: {
          address: current.address,
          chainId: current.chainId,
          connectorId: current.uid,
          walletName: current.walletName,
          walletSource:
            current.kind === "embedded-session"
              ? "embedded"
              : current.kind === "walletconnect"
                ? "walletconnect"
                : undefined,
        },
        disconnectedAt: null,
      },
    };
  }

  if (!previous.evmGrace.last) return next;
  return {
    ...next,
    evmGrace: {
      last: previous.evmGrace.last,
      disconnectedAt: previous.evmGrace.disconnectedAt ?? now,
    },
  };
}

function externalHealExpected(
  connections: readonly RegistryConnection[],
): WalletRegistryState["heal"]["expected"] {
  const seen = new Set<string>();
  const expected: WalletRegistryState["heal"]["expected"] = [];
  for (const connection of connections) {
    if (connection.family !== "evm" || connection.kind !== "external-evm") {
      continue;
    }
    const key = `${connection.stableId}:${connection.address.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    expected.push({
      stableId: connection.stableId,
      address: connection.address.toLowerCase(),
    });
  }
  return expected;
}

function expectedIsLive(
  connections: readonly RegistryConnection[],
  expected: { stableId: string; address: string },
): boolean {
  return connections.some(
    (connection) =>
      connection.family === "evm" &&
      connection.stableId === expected.stableId &&
      connection.address.toLowerCase() === expected.address.toLowerCase(),
  );
}

function expectedConnectorIsLive(
  connections: readonly RegistryConnection[],
  expected: { stableId: string },
): boolean {
  return connections.some(
    (connection) =>
      connection.family === "evm" && connection.stableId === expected.stableId,
  );
}

function nextHealExpectedOnSettled(
  state: WalletRegistryState,
): WalletRegistryState["heal"]["expected"] {
  const missingExpected = state.heal.expected.filter(
    (expected) =>
      !expectedIsLive(state.connections, expected) &&
      !expectedConnectorIsLive(state.connections, expected),
  );
  return missingExpected.length > 0
    ? state.heal.expected
    : externalHealExpected(state.connections);
}

function addDroppedAddress(
  droppedAddresses: readonly string[],
  address: string,
): string[] {
  const normalized = address.toLowerCase();
  return droppedAddresses.includes(normalized)
    ? [...droppedAddresses]
    : [...droppedAddresses, normalized];
}

function dropAddressMatches(
  active: ActiveRef | undefined,
  address: string,
): boolean {
  return !!active && active.address.toLowerCase() === address.toLowerCase();
}

function connectionSignature(
  connections: readonly RegistryConnection[],
): string {
  return JSON.stringify(
    connections
      .map((connection) => ({
        family: connection.family,
        uid: connection.uid,
        stableId: connection.stableId,
        kind: connection.kind,
        address:
          connection.family === "evm"
            ? connection.address.toLowerCase()
            : connection.address,
        addresses: connection.addresses.map((address) =>
          connection.family === "evm" ? address.toLowerCase() : address,
        ),
        chainId: connection.chainId ?? null,
        walletName: connection.walletName ?? null,
      }))
      .sort((left, right) =>
        `${left.family}:${left.uid}:${left.address}`.localeCompare(
          `${right.family}:${right.uid}:${right.address}`,
        ),
      ),
  );
}

export function reduce(
  state: WalletRegistryState,
  event: RegistryEvent,
): WalletRegistryState {
  switch (event.type) {
    case "boot/init": {
      return {
        ...createInitialState(),
        connectionOrder: event.persisted?.order ?? [],
        activeByFamily: activeFromPersisted(event.persisted),
        intents: {
          droppedAddresses:
            event.persisted?.droppedAddresses.map((item) =>
              item.toLowerCase(),
            ) ?? [],
          providerSessionDetached:
            event.persisted?.providerSessionDetached ?? false,
          explicitFamilyDisconnect: {},
          pendingSvmWallet: null,
          preferEmbeddedOnConnect: false,
        },
      };
    }

    case "wagmi/connections-changed": {
      const connections = event.connections.map((connection) =>
        classifyConnection(connection, state.embeddedSession),
      );
      const currentEvmConnections = state.connections.filter(
        (connection) => connection.family === "evm",
      );
      if (
        connectionSignature(connections) ===
        connectionSignature(currentEvmConnections)
      ) {
        return state;
      }
      const nextPhase = state.phase === "stable" ? "settling" : state.phase;
      let next: WalletRegistryState = withConnectionOrder({
        ...state,
        phase: nextPhase,
        connections: [
          ...connections,
          ...withoutSyntheticEmbeddedSessionConnection(
            state,
            state.connections,
          ).filter((connection) => connection.family === "svm"),
        ],
      });
      next = withEmbeddedSessionConnection(next);
      next = withPreferredEmbeddedSessionActive(next);
      if (state.phase === "stable") {
        next = {
          ...next,
          heal: {
            ...next.heal,
            expected: externalHealExpected(state.connections),
          },
        };
      }
      next = withResolvedActive(next, ["evm"]);
      return withEvmGrace(state, next, event.now);
    }

    case "wagmi/config-rebuilt":
      return {
        ...state,
        phase: "rebuilding",
        heal: {
          ...state.heal,
          expected:
            state.phase === "stable"
              ? externalHealExpected(state.connections)
              : state.heal.expected,
        },
      };

    case "wagmi/brands-changed": {
      let changed = false;
      const connections = state.connections.map((connection) => {
        const walletName =
          event.brands[connection.uid] ?? connection.walletName;
        if (walletName !== connection.walletName) changed = true;
        return { ...connection, walletName };
      });
      if (!changed) return state;
      return {
        ...state,
        ...withConnectionOrder({ ...state, connections }),
      };
    }

    case "wagmi/settled": {
      const stateForHeal = { ...state, phase: state.phase };
      const spentBudget =
        state.phase === "stable"
          ? countPlannedHealConnects(stateForHeal, event.now)
          : 0;
      let next: WalletRegistryState = {
        ...state,
        phase: "stable",
        heal: {
          ...state.heal,
          expected: nextHealExpectedOnSettled(state),
          reattachBudget: Math.max(0, state.heal.reattachBudget - spentBudget),
        },
      };
      next = withResolvedActive(next);
      return withEvmGrace(state, next, event.now);
    }

    case "provider/embedded-session-changed": {
      let next: WalletRegistryState = {
        ...state,
        phase: state.phase === "booting" ? "settling" : state.phase,
        embeddedSession: {
          up: event.up,
          providerId: event.providerId,
          uid: event.uid,
          stableId: event.stableId,
          walletName: event.walletName,
          embeddedEvmAddress: event.embeddedEvmAddress?.toLowerCase() ?? null,
          chainId: event.chainId ?? null,
        },
      };
      next = withEmbeddedSessionConnection(next);
      next = withPreferredEmbeddedSessionActive(next);
      next = withResolvedActive(next, ["evm"]);
      return withEvmGrace(state, next, event.now);
    }

    case "provider/auth-flow-started":
      return {
        ...state,
        heal: {
          ...state.heal,
          suppressedUntil: event.now + REATTACH_SUPPRESSION_MS,
          suppressionReason: event.reason,
        },
      };

    case "svm/changed": {
      const uid = event.uid ?? event.walletName ?? event.publicKey;
      const stableId = event.stableId ?? uid;
      const connections = state.connections.filter(
        (connection) =>
          connection.family !== "svm" ||
          (event.stableId
            ? connection.stableId !== event.stableId
            : connection.kind !== "svm"),
      );
      const pendingConnected =
        event.publicKey &&
        state.intents.pendingSvmWallet &&
        event.walletName === state.intents.pendingSvmWallet;
      if (event.publicKey && uid && stableId) {
        connections.push({
          key: `solana:${uid}`,
          family: "svm",
          uid,
          stableId,
          kind: event.kind ?? "svm",
          address: event.publicKey,
          addresses: [event.publicKey],
          walletName: event.walletName ?? undefined,
          providerId: event.providerId,
        });
      }
      let next: WalletRegistryState = withConnectionOrder({
        ...state,
        connections,
        intents: {
          ...state.intents,
          pendingSvmWallet: pendingConnected
            ? null
            : state.intents.pendingSvmWallet,
        },
      });
      if (pendingConnected && event.publicKey) {
        next = {
          ...next,
          activeByFamily: {
            ...next.activeByFamily,
            svm: {
              family: "svm",
              address: event.publicKey,
              uid: uid ?? event.publicKey,
              stableId: stableId ?? event.publicKey,
            },
          },
        };
      }
      return withResolvedActive(next, ["svm"]);
    }

    case "svm/connect-requested":
      return {
        ...state,
        intents: {
          ...state.intents,
          pendingSvmWallet: event.walletName,
        },
      };

    case "svm/connect-settled":
      if (state.intents.pendingSvmWallet !== event.walletName) return state;
      return {
        ...state,
        intents: {
          ...state.intents,
          pendingSvmWallet: null,
        },
      };

    case "user/select-active":
      return {
        ...state,
        activeByFamily: {
          ...state.activeByFamily,
          [event.family]: {
            family: event.family,
            address:
              event.family === "evm"
                ? event.address.toLowerCase()
                : event.address,
            uid: event.uid,
            stableId: event.stableId,
          },
        },
        intents: {
          ...state.intents,
          preferEmbeddedOnConnect: false,
          explicitFamilyDisconnect: {
            ...state.intents.explicitFamilyDisconnect,
            [event.family]: false,
          },
        },
      };

    case "user/connect-succeeded":
      return {
        ...state,
        activeByFamily: {
          ...state.activeByFamily,
          [event.family]: {
            family: event.family,
            address:
              event.family === "evm"
                ? event.address.toLowerCase()
                : event.address,
            uid: event.uid,
            stableId: event.stableId,
          },
        },
        intents: {
          ...state.intents,
          droppedAddresses:
            event.family === "evm"
              ? state.intents.droppedAddresses.filter(
                  (address) => address !== event.address.toLowerCase(),
                )
              : state.intents.droppedAddresses,
          providerSessionDetached:
            event.family === "evm" &&
            event.stableId === state.embeddedSession.stableId
              ? false
              : state.intents.providerSessionDetached,
          explicitFamilyDisconnect: {
            ...state.intents.explicitFamilyDisconnect,
            [event.family]: false,
          },
          preferEmbeddedOnConnect: false,
        },
      };

    case "user/provider-reconnect-requested":
      return withPreferredEmbeddedSessionActive(
        withEmbeddedSessionConnection({
          ...state,
          intents: {
            ...state.intents,
            providerSessionDetached: false,
            preferEmbeddedOnConnect: true,
          },
        }),
      );

    case "user/disconnect-account": {
      const filtered = state.connections.filter(
        (connection) => !event.uids.includes(connection.uid),
      );
      const activeByFamily = { ...state.activeByFamily };
      if (dropAddressMatches(activeByFamily.evm, event.address)) {
        delete activeByFamily.evm;
      }
      let next: WalletRegistryState = withConnectionOrder({
        ...state,
        connections: withoutSyntheticEmbeddedSessionConnection(state, filtered),
        activeByFamily,
        intents: {
          ...state.intents,
          droppedAddresses:
            (event.markDroppedAddress ?? true)
              ? addDroppedAddress(state.intents.droppedAddresses, event.address)
              : [...state.intents.droppedAddresses],
          providerSessionDetached:
            event.isProviderOwnedAccount && event.othersRemain
              ? true
            : state.intents.providerSessionDetached,
        },
      });
      next = withEmbeddedSessionConnection(next);
      next = withResolvedActive(next, ["evm"]);
      return withEvmGrace(state, next, event.now);
    }

    case "user/disconnect-family": {
      const activeByFamily = { ...state.activeByFamily };
      const explicitFamilyDisconnect = {
        ...state.intents.explicitFamilyDisconnect,
      };
      const disconnectsEvm = event.family === "all" || event.family === "evm";
      const disconnectsSvm = event.family === "all" || event.family === "svm";
      if (disconnectsEvm) {
        delete activeByFamily.evm;
        explicitFamilyDisconnect.evm = true;
      }
      if (disconnectsSvm) {
        delete activeByFamily.svm;
        explicitFamilyDisconnect.svm = true;
      }
      let connections = state.connections;
      if (disconnectsEvm) {
        connections = withoutSyntheticEmbeddedSessionConnection(
          state,
          connections,
        );
      }
      if (disconnectsSvm) {
        connections = connections.filter(
          (connection) => connection.family !== "svm",
        );
      }
      let next: WalletRegistryState = withConnectionOrder({
        ...state,
        activeByFamily,
        evmGrace:
          disconnectsEvm
            ? { last: null, disconnectedAt: null }
            : state.evmGrace,
        connections,
        intents: {
          ...state.intents,
          explicitFamilyDisconnect,
          providerSessionDetached:
            disconnectsEvm ? true : state.intents.providerSessionDetached,
        },
      });
      next = withEmbeddedSessionConnection(next);
      return next;
    }

    default:
      return state;
  }
}

import type { WalletFamily } from "../types";
import type {
  ActiveRef,
  RegistryCommand,
  RegistryConnection,
  RegistryEvent,
  WalletRegistryState,
} from "./types";

function normalizeAddress(family: WalletFamily, address: string): string {
  return family === "evm" ? address.toLowerCase() : address;
}

function connectionToActive(connection: RegistryConnection): ActiveRef {
  return {
    family: connection.family,
    address: connection.address,
    uid: connection.uid,
    stableId: connection.stableId,
  };
}

function matchesActive(
  connection: RegistryConnection,
  active: ActiveRef,
  requireStableId: boolean,
): boolean {
  if (connection.family !== active.family) return false;
  if (
    normalizeAddress(connection.family, connection.address) !==
    normalizeAddress(active.family, active.address)
  ) {
    return false;
  }
  if (requireStableId && active.stableId) {
    return connection.stableId === active.stableId;
  }
  return true;
}

function findActiveConnection(
  connections: readonly RegistryConnection[],
  active: ActiveRef,
): RegistryConnection | undefined {
  if (active.uid) {
    const byUid = connections.find(
      (connection) =>
        connection.family === active.family && connection.uid === active.uid,
    );
    if (byUid) return byUid;
  }

  if (active.stableId) {
    const byStableId = connections.find((connection) =>
      matchesActive(connection, active, true),
    );
    if (byStableId) return byStableId;
  }

  return connections.find((connection) =>
    matchesActive(connection, active, false),
  );
}

function connectionIsDropped(
  state: WalletRegistryState,
  connection: RegistryConnection,
): boolean {
  return (
    connection.family === "evm" &&
    state.intents.droppedAddresses.includes(connection.address.toLowerCase())
  );
}

export function resolveActive(
  state: WalletRegistryState,
  family: WalletFamily,
): ActiveRef | undefined {
  const familyConnections = state.connections.filter(
    (connection) =>
      connection.family === family && !connectionIsDropped(state, connection),
  );
  const current = state.activeByFamily[family];

  if (current) {
    const live = findActiveConnection(familyConnections, current);
    if (live) return connectionToActive(live);
    if (state.phase !== "stable") return current;
  }

  if (family === "evm") {
    const firstExternal = familyConnections.find(
      (connection) => connection.kind === "external-evm",
    );
    if (state.phase === "stable" && firstExternal) {
      return connectionToActive(firstExternal);
    }

    if (state.phase === "stable") {
      const embeddedSession = familyConnections.find(
        (connection) => connection.kind === "embedded-session",
      );
      return embeddedSession ? connectionToActive(embeddedSession) : undefined;
    }
    return undefined;
  }

  return familyConnections[0]
    ? connectionToActive(familyConnections[0])
    : undefined;
}

function isDropped(state: WalletRegistryState, address: string): boolean {
  return state.intents.droppedAddresses.includes(address.toLowerCase());
}

function expectedIsLive(
  state: WalletRegistryState,
  expected: { stableId: string; address: string },
): boolean {
  return state.connections.some(
    (connection) =>
      connection.family === "evm" &&
      connection.stableId === expected.stableId &&
      connection.address.toLowerCase() === expected.address.toLowerCase(),
  );
}

function expectedConnectorIsLive(
  state: WalletRegistryState,
  expected: { stableId: string },
): boolean {
  return state.connections.some(
    (connection) =>
      connection.family === "evm" && connection.stableId === expected.stableId,
  );
}

function expectedIsHealEligible(
  state: WalletRegistryState,
  expected: { stableId: string; address: string },
  now: number,
): boolean {
  if (state.intents.explicitFamilyDisconnect.evm) return false;
  if (isDropped(state, expected.address)) return false;
  if (
    expected.stableId === state.embeddedSession.stableId ||
    expected.stableId === "walletConnect"
  ) {
    return false;
  }
  if (
    state.heal.suppressedUntil === null ||
    now >= state.heal.suppressedUntil
  ) {
    return true;
  }
  return (
    state.heal.suppressionReason === "provider-social-login" ||
    state.heal.suppressionReason === "provider-auth-modal" ||
    state.heal.suppressionReason === "provider-evm-connect-fallback" ||
    state.heal.suppressionReason === "provider-account-modal"
  );
}

function expectedIsSilentReconnectEligible(
  state: WalletRegistryState,
  expected: { stableId: string; address: string },
): boolean {
  if (state.intents.explicitFamilyDisconnect.evm) return false;
  if (isDropped(state, expected.address)) return false;
  return (
    expected.stableId !== state.embeddedSession.stableId &&
    expected.stableId !== "walletConnect"
  );
}

export function planHeal(
  state: WalletRegistryState,
  now: number,
): RegistryCommand[] {
  const missing = state.heal.expected.filter(
    (expected) =>
      !expectedIsLive(state, expected) &&
      !expectedConnectorIsLive(state, expected),
  );
  if (missing.length === 0) return [];
  const silentReconnectEligible = missing.filter((expected) =>
    expectedIsSilentReconnectEligible(state, expected),
  );
  if (silentReconnectEligible.length === 0) return [];

  if (state.phase !== "stable") {
    return [
      {
        kind: "wagmi/reconnect",
        stableIds: [
          ...new Set(
            silentReconnectEligible.map((expected) => expected.stableId),
          ),
        ],
      },
      {
        kind: "debug",
        event: "evm:heal",
        data: {
          action: "reconnect",
          phase: state.phase,
          missing: silentReconnectEligible.length,
          suppressed: Boolean(
            state.heal.suppressedUntil !== null &&
            now < state.heal.suppressedUntil,
          ),
        },
      },
    ];
  }

  const commands: RegistryCommand[] = [];
  let budget = state.heal.reattachBudget;
  for (const expected of missing) {
    if (budget <= 0) break;
    if (!expectedIsHealEligible(state, expected, now)) continue;
    if (
      !commands.some(
        (command) =>
          command.kind === "wagmi/connect" &&
          command.stableId === expected.stableId,
      )
    ) {
      commands.push({ kind: "wagmi/connect", stableId: expected.stableId });
    }
    budget -= 1;
  }
  if (commands.length > 0) {
    commands.push({
      kind: "debug",
      event: "evm:heal",
      data: { action: "connect", count: commands.length },
    });
  }
  return commands;
}

export function countPlannedHealConnects(
  state: WalletRegistryState,
  now: number,
): number {
  return planHeal(state, now).filter(
    (command) => command.kind === "wagmi/connect",
  ).length;
}

export function planDisconnect(
  state: WalletRegistryState,
  event: Extract<
    RegistryEvent,
    { type: "user/disconnect-account" | "user/disconnect-family" }
  >,
): RegistryCommand[] {
  if (event.type === "user/disconnect-family") {
    const families =
      event.family === "all" ? (["evm", "svm"] as const) : [event.family];
    const commands: RegistryCommand[] = [];
    if (families.includes("evm")) {
      for (const connection of state.connections) {
        if (
          connection.family === "evm" &&
          connection.uid !== state.embeddedSession.uid
        ) {
          commands.push({ kind: "wagmi/disconnect", uid: connection.uid });
        }
      }
    }
    if (families.includes("svm")) {
      commands.push({ kind: "svm/disconnect" });
    }
    if (event.family === "all") commands.push({ kind: "provider/logout" });
    return commands;
  }

  const commands: RegistryCommand[] = event.uids.map((uid) => ({
    kind: "wagmi/disconnect",
    uid,
  }));
  if (event.isProviderOwnedAccount && !event.othersRemain) {
    commands.push({ kind: "provider/logout" });
  }
  return commands;
}

import { planDisconnect, planHeal } from "./policy";
import type {
  PersistedRegistryV1,
  RegistryCommand,
  RegistryEvent,
  WalletRegistryState,
} from "./types";
import { toPersisted } from "./persistence";

function stableJson(value: unknown): string {
  return JSON.stringify(value);
}

function persistableChanged(
  prev: WalletRegistryState,
  next: WalletRegistryState,
): boolean {
  const prevPersisted: PersistedRegistryV1 = toPersisted(prev);
  const nextPersisted: PersistedRegistryV1 = toPersisted(next);
  return stableJson(prevPersisted) !== stableJson(nextPersisted);
}

export function planCommands(
  prev: WalletRegistryState,
  next: WalletRegistryState,
  event: RegistryEvent,
): RegistryCommand[] {
  const commands: RegistryCommand[] = [
    {
      kind: "debug",
      event: "registry:event",
      data: { type: event.type, phase: next.phase },
    },
  ];

  if (event.type === "wagmi/settled") {
    commands.push(
      ...planHeal(
        {
          ...next,
          phase: prev.phase,
          heal: {
            ...next.heal,
            reattachBudget: prev.heal.reattachBudget,
          },
        },
        event.now,
      ),
    );
  }

  if (
    event.type === "user/disconnect-account" ||
    event.type === "user/disconnect-family"
  ) {
    commands.push(...planDisconnect(prev, event));
  }

  if (event.type === "svm/connect-requested") {
    commands.push({ kind: "svm/connect", walletName: event.walletName });
  }

  if (event.type === "user/select-active") {
    commands.push({
      kind: "debug",
      event: "active-evm:user-select",
      data: {
        family: event.family,
        address: event.address,
        stableId: event.stableId,
      },
    });
  }

  if (event.type === "boot/init" && next.activeByFamily.evm) {
    commands.push({
      kind: "debug",
      event: "active-evm:persisted",
      data: {
        address: next.activeByFamily.evm.address,
        stableId: next.activeByFamily.evm.stableId,
      },
    });
  }

  if (persistableChanged(prev, next)) {
    commands.push({ kind: "persist" });
  }

  return commands;
}

import type { PersistedRegistryV1, WalletRegistryState } from "./types";
import { REGISTRY_STORAGE_KEY } from "./types";
import { toRegistryFamily } from "../wallet-utils";

// Frozen legacy localStorage identifiers from pre-registry builds. The key
// string and the `paraDetached` field (read below) name Para only for
// historical reasons: they migrate real data written by older clients and must
// run in every mode — including a wallets-only build opened by a user whose
// previous Para session left a detached address. Moving them into
// providers/para would skip that migration whenever Para isn't mounted, so they
// stay core. Do not rename the string values; they must match what was written.
const LEGACY_ACTIVE_EVM_ADDRESS_KEY = "aomi.wallet.active-evm-address";
const LEGACY_DETACHED_PARA_EVM_ADDRESS_KEY =
  "aomi.wallet.detached-para-evm-address";

export type LoadPersistedOptions = {
  migrateDestructively?: boolean;
};

function isPersistedRegistryV1(value: unknown): value is PersistedRegistryV1 {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Partial<PersistedRegistryV1> & {
    paraDetached?: unknown;
  };
  return (
    candidate.version === 1 &&
    typeof candidate.active === "object" &&
    candidate.active !== null &&
    Array.isArray(candidate.droppedAddresses) &&
    (typeof candidate.providerSessionDetached === "boolean" ||
      typeof candidate.paraDetached === "boolean")
  );
}

function normalizePersisted(value: PersistedRegistryV1): PersistedRegistryV1 {
  return {
    ...value,
    order: Array.isArray(value.order)
      ? value.order
          .filter((item) => {
            const family = (item as { family?: unknown } | null)?.family;
            return (
              item &&
              (family === "evm" || family === "svm") &&
              typeof item.stableId === "string" &&
              typeof item.address === "string"
            );
          })
          .map((item) => {
            const registryFamily = toRegistryFamily(item.family);
            return {
              family: registryFamily,
              stableId: item.stableId,
              address:
                registryFamily === "evm"
                  ? item.address.toLowerCase()
                  : item.address,
            };
          })
      : [],
    providerSessionDetached:
      value.providerSessionDetached ?? false,
  };
}

function readStorage(key: string): string | null {
  try {
    return globalThis.localStorage?.getItem(key) ?? null;
  } catch {
    return null;
  }
}

function writeStorage(key: string, value: string): void {
  try {
    globalThis.localStorage?.setItem(key, value);
  } catch {
    // Best effort: wallet preferences should never break rendering.
  }
}

function removeStorage(key: string): void {
  try {
    globalThis.localStorage?.removeItem(key);
  } catch {
    // Best effort.
  }
}

function migrateLegacyKeys(
  storageKey: string,
  options: LoadPersistedOptions,
): PersistedRegistryV1 | null {
  const legacyActiveEvm = readStorage(LEGACY_ACTIVE_EVM_ADDRESS_KEY);
  const legacyDetachedPara = readStorage(LEGACY_DETACHED_PARA_EVM_ADDRESS_KEY);
  if (!legacyActiveEvm && !legacyDetachedPara) return null;

  const migrated: PersistedRegistryV1 = {
    version: 1,
    active: legacyActiveEvm
      ? { evm: { address: legacyActiveEvm.toLowerCase() } }
      : {},
    droppedAddresses: legacyDetachedPara
      ? [legacyDetachedPara.toLowerCase()]
      : [],
    order: [],
    providerSessionDetached: !!legacyDetachedPara,
  };

  writeStorage(storageKey, JSON.stringify(migrated));
  if (options.migrateDestructively) {
    removeStorage(LEGACY_ACTIVE_EVM_ADDRESS_KEY);
    removeStorage(LEGACY_DETACHED_PARA_EVM_ADDRESS_KEY);
  }
  return migrated;
}

export function loadPersisted(
  storageKey = REGISTRY_STORAGE_KEY,
  options: LoadPersistedOptions = {},
): PersistedRegistryV1 | null {
  try {
    const raw = readStorage(storageKey);
    if (!raw) return migrateLegacyKeys(storageKey, options);
    const parsed: unknown = JSON.parse(raw);
    return isPersistedRegistryV1(parsed) ? normalizePersisted(parsed) : null;
  } catch {
    return null;
  }
}

export function toPersisted(state: WalletRegistryState): PersistedRegistryV1 {
  return {
    version: 1,
    active: {
      ...(state.activeByFamily.evm
        ? {
            evm: {
              address: state.activeByFamily.evm.address.toLowerCase(),
              stableId: state.activeByFamily.evm.stableId,
            },
          }
        : {}),
      ...(state.activeByFamily.svm
        ? {
            svm: {
              address: state.activeByFamily.svm.address,
              stableId: state.activeByFamily.svm.stableId,
            },
          }
        : {}),
    },
    order: state.connectionOrder.map((item) => ({
      family: item.family,
      stableId: item.stableId,
      address: item.family === "evm" ? item.address.toLowerCase() : item.address,
    })),
    droppedAddresses: state.intents.droppedAddresses.map((item) =>
      item.toLowerCase(),
    ),
    providerSessionDetached: state.intents.providerSessionDetached,
  };
}

export function savePersisted(
  state: WalletRegistryState,
  storageKey = REGISTRY_STORAGE_KEY,
): void {
  writeStorage(storageKey, JSON.stringify(toPersisted(state)));
}

import { walletDebug } from "../wallet-debug";
import { planCommands } from "./commands";
import { loadPersisted, savePersisted } from "./persistence";
import { createInitialState, reduce } from "./reducer";
import type {
  RegistryCommand,
  RegistryEvent,
  WalletRegistryState,
} from "./types";
import { AUTH_FLOW_RECONNECT_SETTLE_MS, SETTLE_QUIET_MS } from "./types";

export type CommandExecutors = {
  wagmiReconnect(stableIds: string[]): Promise<void>;
  wagmiConnect(stableId: string): Promise<void>;
  wagmiDisconnect(uid: string): Promise<void>;
  svmConnect?(walletName: string): Promise<void>;
  svmDisconnect?(): Promise<void>;
  providerLogout(): Promise<void>;
};

export class WalletRegistryStore {
  private state: WalletRegistryState;
  private readonly subscribers = new Set<() => void>();
  private executors: CommandExecutors;
  private readonly storageKey: string;
  private settleTimer: number | null = null;

  constructor(opts: {
    executors: CommandExecutors;
    storageKey: string;
    initialNow: number;
  }) {
    this.executors = opts.executors;
    this.storageKey = opts.storageKey;
    const prev = createInitialState();
    const event: RegistryEvent = {
      type: "boot/init",
      persisted: loadPersisted(opts.storageKey, { migrateDestructively: true }),
      now: opts.initialNow,
    };
    this.state = reduce(prev, event);
    for (const command of planCommands(prev, this.state, event)) {
      this.executeCommand(command);
    }
  }

  getSnapshot(): WalletRegistryState {
    return this.state;
  }

  subscribe(cb: () => void): () => void {
    this.subscribers.add(cb);
    return () => {
      this.subscribers.delete(cb);
    };
  }

  updateExecutors(executors: Partial<CommandExecutors>): void {
    this.executors = { ...this.executors, ...executors };
  }

  dispatch(event: RegistryEvent): void {
    const prev = this.state;
    const next = reduce(prev, event);
    if (next === prev) return;

    this.state = next;
    for (const subscriber of this.subscribers) subscriber();

    const commands = planCommands(prev, next, event);
    for (const command of commands) {
      this.executeCommand(command);
    }

    if (event.type.startsWith("wagmi/") && event.type !== "wagmi/settled") {
      this.scheduleSettledPass(SETTLE_QUIET_MS);
    }
  }

  dispose(): void {
    if (this.settleTimer !== null && typeof window !== "undefined") {
      window.clearTimeout(this.settleTimer);
    }
    this.settleTimer = null;
  }

  private executeCommand(command: RegistryCommand): void {
    switch (command.kind) {
      case "persist":
        savePersisted(this.state, this.storageKey);
        break;
      case "debug":
        walletDebug(command.event, command.data);
        break;
      case "wagmi/reconnect":
        this.runAsync(command.kind, async () => {
          try {
            await this.executors.wagmiReconnect(command.stableIds);
          } finally {
            this.scheduleSettledPass(this.reconnectSettleDelayMs());
          }
        });
        break;
      case "wagmi/connect":
        this.runAsync(command.kind, () =>
          this.executors.wagmiConnect(command.stableId),
        );
        break;
      case "wagmi/disconnect":
        this.runAsync(command.kind, () =>
          this.executors.wagmiDisconnect(command.uid),
        );
        break;
      case "svm/connect":
        if (this.executors.svmConnect) {
          this.runAsync(command.kind, () =>
            this.executors.svmConnect!(command.walletName),
          );
        }
        break;
      case "svm/disconnect":
        if (this.executors.svmDisconnect) {
          this.runAsync(command.kind, () => this.executors.svmDisconnect!());
        }
        break;
      case "provider/logout":
        this.runAsync(command.kind, () => this.executors.providerLogout());
        break;
      default:
        break;
    }
  }

  private runAsync(
    kind: RegistryCommand["kind"],
    fn: () => Promise<void>,
  ): void {
    void fn().catch((error: unknown) => {
      walletDebug("registry:command-error", {
        kind,
        error: error instanceof Error ? error.message : String(error),
      });
    });
  }

  private reconnectSettleDelayMs(): number {
    const authFlowSuppressed =
      this.state.heal.suppressedUntil !== null &&
      Date.now() < this.state.heal.suppressedUntil &&
      (this.state.heal.suppressionReason === "provider-social-login" ||
        this.state.heal.suppressionReason === "provider-auth-modal" ||
        this.state.heal.suppressionReason === "provider-evm-connect-fallback" ||
        this.state.heal.suppressionReason === "provider-account-modal");
    return authFlowSuppressed ? AUTH_FLOW_RECONNECT_SETTLE_MS : SETTLE_QUIET_MS;
  }

  private scheduleSettledPass(delayMs: number): void {
    const run = () => {
      this.settleTimer = null;
      this.dispatch({ type: "wagmi/settled", now: Date.now() });
    };
    if (typeof window === "undefined") {
      queueMicrotask(run);
      return;
    }
    if (this.settleTimer !== null) {
      window.clearTimeout(this.settleTimer);
    }
    this.settleTimer = window.setTimeout(run, delayMs);
  }
}

import { buildAccounts } from "../accounts";
import type { AomiAccount, WalletFamily, WalletSource } from "../types";
import { resolveGracefulEvmIdentity } from "./identity-grace";
import { EVM_IDENTITY_GRACE_MS } from "./types";
import type {
  ActiveRef,
  RegistryConnection,
  WalletRegistryState,
} from "./types";

export function selectActiveEvm(
  state: WalletRegistryState,
): ActiveRef | undefined {
  return state.activeByFamily.evm;
}

export function selectSvm(
  state: WalletRegistryState,
): RegistryConnection | undefined {
  const active = state.activeByFamily.svm;
  if (active) {
    return state.connections.find(
      (connection) =>
        connection.family === "svm" &&
        connection.address === active.address &&
        (!active.uid || connection.uid === active.uid),
    );
  }
  return state.connections.find((connection) => connection.family === "svm");
}

function findActiveConnection(
  state: WalletRegistryState,
  family: WalletFamily,
): RegistryConnection | undefined {
  const active = state.activeByFamily[family];
  if (!active) return undefined;
  return state.connections.find((connection) => {
    if (connection.family !== family) return false;
    if (active.uid && connection.uid === active.uid) return true;
    if (active.stableId && connection.stableId !== active.stableId) {
      return false;
    }
    const left =
      family === "evm" ? connection.address.toLowerCase() : connection.address;
    const right =
      family === "evm" ? active.address.toLowerCase() : active.address;
    return left === right;
  });
}

export type EvmIdentity = {
  address?: string;
  chainId?: number;
  connectorId?: string;
  walletName?: string;
  walletSource?: WalletSource;
};

export function selectEvmIdentity(
  state: WalletRegistryState,
  now: number,
  selectedChainId?: number,
): EvmIdentity {
  const activeConnection = findActiveConnection(state, "evm");
  const walletSource: WalletSource | undefined =
    activeConnection?.kind === "embedded-session"
      ? "embedded"
      : activeConnection?.kind === "walletconnect"
        ? "walletconnect"
        : undefined;
  const current = activeConnection
    ? {
        address: activeConnection.address,
        chainId: activeConnection.chainId ?? selectedChainId,
        connectorId: activeConnection.uid,
        walletName: activeConnection.walletName,
        walletSource,
      }
    : selectedChainId === undefined
      ? {}
      : { chainId: selectedChainId };
  const explicitDisconnect = Boolean(
    state.evmGrace.last?.address &&
    state.intents.droppedAddresses.includes(
      state.evmGrace.last.address.toLowerCase(),
    ),
  );

  return resolveGracefulEvmIdentity({
    current,
    previous: state.evmGrace.last,
    selectedChainId,
    disconnectedAt: state.evmGrace.disconnectedAt,
    now,
    graceMs: EVM_IDENTITY_GRACE_MS,
    explicitDisconnect,
  }).identity;
}

export function selectSvmIdentity(
  state: WalletRegistryState,
  _now: number,
): {
  address?: string;
  walletName?: string;
} {
  const activeConnection = findActiveConnection(state, "svm") ?? selectSvm(state);
  return activeConnection
    ? {
        address: activeConnection.address,
        walletName: activeConnection.walletName,
      }
    : {};
}

export function selectAccounts(
  state: WalletRegistryState,
  family: WalletFamily,
  now: number,
  selectedChainId?: number,
): AomiAccount[] {
  const activeEvm = family === "evm" ? state.activeByFamily.evm : undefined;
  const evmIdentity =
    family === "evm" ? selectEvmIdentity(state, now, selectedChainId) : {};
  const evmConnections =
    family === "evm"
      ? state.connections
          .filter((connection) => connection.family === "evm")
          .map((connection) => ({
            id: connection.uid,
            walletName: connection.walletName ?? connection.stableId,
            address: connection.address,
            chainId: connection.chainId ?? selectedChainId,
            provider: connection.providerId,
            walletKind:
              connection.kind === "embedded-session"
                ? ("embedded" as const)
                : undefined,
          }))
      : [];

  if (evmIdentity.address && evmConnections.length === 0) {
    evmConnections.push({
      id: evmIdentity.connectorId ?? "cached-evm",
      walletName: evmIdentity.walletName ?? "Wallet",
      address: evmIdentity.address,
      chainId: evmIdentity.chainId,
      provider: undefined,
      walletKind: undefined,
    });
  }

  const activeSvm = family === "svm" ? selectSvm(state) : undefined;
  const svmConnections =
    family === "svm"
      ? state.connections.filter((connection) => connection.family === "svm")
      : [];
  return buildAccounts({
    evmConnections,
    activeEvmAddress: evmIdentity.address,
    activeEvmConnectionId: activeEvm?.uid ?? evmIdentity.connectorId,
    svmConnections: svmConnections.map((connection) => ({
      id: connection.uid,
      publicKey: connection.address,
      walletName: connection.walletName,
      provider: connection.providerId,
      walletKind:
        connection.kind === "embedded-session" ? "embedded" : undefined,
    })),
    activeSvmAddress: activeSvm?.address,
  });
}

"use client";

import { useCallback } from "react";
import { useOptionalAomiRuntime } from "@aomi-labs/react";

export function useWalletActivationGuard(): () => boolean {
  const runtime = useOptionalAomiRuntime();

  return useCallback(() => {
    if (!runtime?.hasBlockingActions) {
      return true;
    }

    runtime.showNotification({
      type: "wallet",
      title: "Finish the pending action",
      message:
        "Approve or reject the current action before switching wallets or networks.",
    });
    return false;
  }, [runtime]);
}

"use client";

import { useMemo } from "react";
import {
  Connection as SolanaConnection,
  Transaction as SolanaLegacyTransaction,
  VersionedTransaction,
} from "@solana/web3.js";
import {
  normalizeSolanaCluster,
  parseChainId,
  walletCapabilities,
  type ActionCapabilities,
  type EvmWallet,
  type SvmWallet,
  type WalletSolanaSignPayload,
  type WalletTxPayload,
} from "@aomi-labs/client";

import { useAomiWalletKit } from "./context";

/** Adapts wallet-kit methods into the wallet subroutines used by ActionHandler. */
export function useActionCapabilities(): ActionCapabilities {
  const wallet = useAomiWalletKit();
  return useMemo(
    () =>
      walletCapabilities({
        ...(wallet.identity.address ? { evm: evmWallet(wallet) } : {}),
        ...(wallet.identity.svmAddress ? { svm: svmWallet(wallet) } : {}),
      }),
    [wallet],
  );
}

function evmWallet(wallet: ReturnType<typeof useAomiWalletKit>): EvmWallet {
  const address = wallet.identity.address;
  if (!address) throw new Error("No EVM wallet is active");
  const sendCalls = wallet.sendTransaction
    ? async ({
      chainId,
      calls,
      }: Parameters<NonNullable<EvmWallet["sendCalls"]>>[0]) => {
        const payload: WalletTxPayload = {
          requestId: "action",
          chainId,
          calls: calls.map((call, index) => ({
            ...call,
            txId: index + 1,
            chainId,
            from: address,
          })),
          txIds: calls.map((_, index) => index + 1),
        };
        const result = await wallet.sendTransaction!(payload, {
          chainIdAlreadySelected: chainId,
        });
        return { hash: result.txHash, hashes: result.txHashes };
      }
    : undefined;

  return {
    address,
    chainId: () => wallet.identity.chainId,
    switchChain: (chainId) => switchEvm(wallet, chainId),
    sendCalls,
    signMessage: wallet.signMessage
      ? async ({ message, chainId }) =>
          wallet.signMessage!({
            non_typed_data: message,
            signer: address,
            chainId,
          })
      : undefined,
    signTypedData: wallet.signTypedData
      ? async ({ typedData, chainId }) =>
          wallet.signTypedData!({
            typed_data: typedData,
            signer: address,
            chainId,
          })
      : undefined,
  };
}

function svmWallet(wallet: ReturnType<typeof useAomiWalletKit>): SvmWallet {
  const address = wallet.identity.svmAddress;
  if (!address) throw new Error("No SVM wallet is active");
  const payload = (
    transactionBase64: string,
    cluster?: string,
  ): WalletSolanaSignPayload => ({
    requestId: "action",
    unsignedTx: transactionBase64,
    cluster,
  });

  return {
    address,
    cluster: () => wallet.selectedSolanaNetwork?.cluster,
    switchCluster: (cluster) => switchSvm(wallet, cluster),
    signTransaction: wallet.signSolanaTransaction
      ? async ({ transactionBase64, cluster }) => {
          const result = await wallet.signSolanaTransaction!(
            payload(transactionBase64, cluster),
          );
          return {
            signedTransaction: result.signedTx,
            signature: extractPayerSignature(result.signedTx),
          };
        }
      : undefined,
    signAndSendTransaction: canSendSvm(wallet)
      ? async ({ transactionBase64, cluster }) => {
          const result = await sendSvm(
            wallet,
            payload(transactionBase64, cluster),
          );
          return {
            signature: result.signature,
            signedTransaction: result.signedTx,
          };
        }
      : undefined,
    signMessage: wallet.signSolanaMessage
      ? async ({ messageBase64, cluster }) => {
          return wallet.signSolanaMessage!({
            message: messageBase64,
            cluster,
          });
        }
      : undefined,
  };
}

async function switchEvm(
  wallet: ReturnType<typeof useAomiWalletKit>,
  chainId: number,
): Promise<void> {
  if (chainId === wallet.identity.chainId) return;
  const supported = wallet.supportedNetworks?.evm?.some(
    (network) => parseChainId(network.id) === chainId,
  );
  if (supported === false || !wallet.switchChain) {
    throw new Error(`The active wallet cannot switch to chain ${chainId}`);
  }
  await wallet.switchChain(chainId);
}

async function switchSvm(
  wallet: ReturnType<typeof useAomiWalletKit>,
  cluster?: string,
): Promise<void> {
  const normalized = normalizeSolanaCluster(cluster);
  if (!normalized) return;
  const target = wallet.supportedNetworks?.solana?.find(
    (network) => network.cluster === normalized,
  );
  if (!target) throw new Error(`Unsupported Solana cluster: ${normalized}`);
  if (wallet.selectedSolanaNetwork?.id === target.id) return;
  if (!wallet.selectNetwork || wallet.solanaNetworkSwitchRequiresReconnect) {
    throw new Error(
      `Reconnect the Solana wallet on ${normalized} before signing`,
    );
  }
  await wallet.selectNetwork({ family: "svm", networkId: target.id });
}

function canSendSvm(wallet: ReturnType<typeof useAomiWalletKit>): boolean {
  return Boolean(
    wallet.signAndSendSolanaTransaction ||
    wallet.sendSolanaTransaction ||
    (wallet.signSolanaTransaction && wallet.solanaRpcHttpUrl),
  );
}

async function sendSvm(
  wallet: ReturnType<typeof useAomiWalletKit>,
  payload: WalletSolanaSignPayload,
): Promise<{ signature: string; signedTx?: string }> {
  if (wallet.signAndSendSolanaTransaction) {
    return wallet.signAndSendSolanaTransaction(payload);
  }
  if (wallet.sendSolanaTransaction)
    return wallet.sendSolanaTransaction(payload);
  if (wallet.signSolanaTransaction && wallet.solanaRpcHttpUrl) {
    const signed = await wallet.signSolanaTransaction(payload);
    const connection = new SolanaConnection(
      wallet.solanaRpcHttpUrl,
      "confirmed",
    );
    const signature = await connection.sendRawTransaction(
      decodeBase64(signed.signedTx),
    );
    await connection.confirmTransaction(signature, "confirmed");
    return { signature, signedTx: signed.signedTx };
  }
  throw new Error("Solana wallet provider is not ready");
}

function extractPayerSignature(signedTransaction: string): string {
  const bytes = decodeBase64(signedTransaction);
  let signature: Uint8Array | null = null;
  try {
    signature = VersionedTransaction.deserialize(bytes).signatures[0] ?? null;
  } catch {
    const legacy = SolanaLegacyTransaction.from(bytes).signature;
    signature = legacy ? new Uint8Array(legacy) : null;
  }
  if (!signature || signature.every((byte) => byte === 0)) {
    throw new Error("The signed transaction carries no payer signature");
  }
  return encodeBase64(signature);
}

function decodeBase64(value: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return new Uint8Array(Buffer.from(value, "base64"));
  }
  return Uint8Array.from(atob(value), (character) => character.charCodeAt(0));
}

function encodeBase64(bytes: Uint8Array): string {
  if (typeof Buffer !== "undefined")
    return Buffer.from(bytes).toString("base64");
  return btoa(String.fromCharCode(...bytes));
}

